#### Вариант 1: Адаптировать код
Модифицируй код, чтобы он обрабатывал как группы, так и меши с именами из `validGroups`. Вот как это можно сделать:

```javascript
export function initCube(sceneArg, worldArg, onLoadCallback) {
    scene = sceneArg;
    world = worldArg;

    initCannon();

    loaderGLTF.load(
        "models/Cubik-Rubik_LITE_without_camera.glb",
        (gltf) => {
            const model = gltf.scene;
            model.scale.set(1, 1, 1);
            scene.add(model);

            console.log('***Структура модели***');
            model.traverse(child => {
                if (child.isGroup || child.isMesh) {
                    const worldPos = new THREE.Vector3();
                    child.getWorldPosition(worldPos);
                    console.log(`Объект: ${child.name}, Тип: ${child.type}, Позиция: [${worldPos.x.toFixed(2)}, ${worldPos.y.toFixed(2)}, ${worldPos.z.toFixed(2)}]`);
                }
            });

            _objects.length = 0; // Очищаем
            model.traverse(child => {
                // Обрабатываем группы и меши, если их имена есть в validGroups
                if ((child.isGroup || child.isMesh) && validGroups.includes(child.name)) {
                    // Если это группа, обрабатываем её дочерние меши
                    if (child.isGroup) {
                        child.traverse(mesh => {
                            if (mesh.isMesh) {
                                const clonedMaterial = mesh.material.clone();
                                if (mesh.material.emissive) {
                                    clonedMaterial.emissive = mesh.material.emissive.clone();
                                    clonedMaterial.emissiveIntensity = mesh.material.emissiveIntensity;
                                }
                                if (mesh.material.map) clonedMaterial.map = mesh.material.map;
                                originalMaterials.set(mesh.uuid, clonedMaterial);
                                mesh.castShadow = true;
                                mesh.receiveShadow = true;
                                mesh.material.emissiveIntensity = 0;
                                mesh.geometry.computeVertexNormals();
                                if (!mesh.geometry.boundingBox) mesh.geometry.computeBoundingBox();
                                mesh.raycast = THREE.Mesh.prototype.raycast;
                            }
                        });
                    }
                    // Если это меш (например, Mid5_CENTER_B005), обрабатываем его напрямую
                    if (child.isMesh) {
                        const clonedMaterial = child.material.clone();
                        if (child.material.emissive) {
                            clonedMaterial.emissive = child.material.emissive.clone();
                            clonedMaterial.emissiveIntensity = child.material.emissiveIntensity;
                        }
                        if (child.material.map) clonedMaterial.map = child.material.map;
                        originalMaterials.set(child.uuid, clonedMaterial);
                        child.castShadow = true;
                        child.receiveShadow = true;
                        child.material.emissiveIntensity = 0;
                        child.geometry.computeVertexNormals();
                        if (!child.geometry.boundingBox) child.geometry.computeBoundingBox();
                        child.raycast = THREE.Mesh.prototype.raycast;
                    }

                    // Создаём физическое тело
                    const worldPos = new THREE.Vector3();
                    child.getWorldPosition(worldPos);
                    const body = new CANNON.Body({
                        mass: 1, // Для центральных кубиков можно использовать mass: 0, если они неподвижны
                        position: new CANNON.Vec3(worldPos.x, worldPos.y, worldPos.z),
                        shape: new CANNON.Box(new CANNON.Vec3(0.5, 0.5, 0.5)),
                        material: new CANNON.Material()
                    });
                    world.addBody(body);
                    bodies.push({ mesh: child, body });

                    _objects.push(child);
                }
            });

            console.log('initCube: Objects filled, length=', _objects.length);
            _objects.forEach((obj, i) => {
                console.log(`Object ${i}: ${obj.name}, Type: ${obj.type}, Children: ${obj.isGroup ? obj.children.length : 0}`);
            });

            if (onLoadCallback) onLoadCallback();
        },
        undefined,
        (error) => {
            console.error("Ошибка загрузки модели:", error);
        }
    );
}
```

**Что изменено**:
- Условие `child.isGroup && validGroups.includes(child.name)` заменено на `(child.isGroup || child.isMesh) && validGroups.includes(child.name)`, чтобы включать и меши.
