const validGroups = [
    'R1_GWR001', 'R2_WR002', 'R3_RWB003', 'R4_GR004', 'R5_CENTER_R005', 'R6_RB006', 'R7_GRY007', 'R8_RY008', 'R9_RBY009',
    'Mid1_GW001', 'Mid2_CENTER_W002', 'Mid3_WB003', 'Mid4_CENTER_G004', 'Mid5_CENTER_B005', 'Mid6_CENTER_B006', 'Mid7_YG007', 'Mid8_CENTER_Y008', 'Mid9_YB009',
    'O1_GOW001', 'O2_OW002', 'O3_OBW003', 'O4_GO004', 'O5_CENTER_O005', 'O6_OB006', 'O7_GYO007', 'O8_YO008', 'O9_OYB009'
];

// Getter для Objects
export function getObjects() {
    return _objects;
}

let rotationGroup = null;
let cubesToRotate = [];
let arrowHelper = null;
let progressArrows = [];
let isRotating = false;
let rotationAxis = new THREE.Vector3();

export function initCube(sceneArg, worldArg, onLoadCallback) {
    scene = sceneArg;
    world = worldArg;

    initCannon();

    loaderGLTF.load("models/Cubik-Rubik_LITE_without_camera_fixCenter.glb",
        (gltf) => {
            const model = gltf.scene;
            model.scale.set(1, 1, 1);
            scene.add(model);

            //console.log('***Структура модели***');
            model.traverse(child => {
                if (child.isGroup || child.isMesh) {
                    const worldPos = new THREE.Vector3();
                    child.getWorldPosition(worldPos);
                    //console.log(`Объект: ${child.name}, Тип: ${child.type}, Позиция: [${worldPos.x.toFixed(2)}, ${worldPos.y.toFixed(2)}, ${worldPos.z.toFixed(2)}]`);
                }
            });

            _objects.length = 0; // Очищаем
            model.traverse(child => {
                if (child.isGroup && validGroups.includes(child.name)) {
                    child.traverse(mesh => {
                        if (mesh.isMesh) {
                            const clonedMaterial = mesh.material.clone();
                            if (mesh.material.emissive) {
                                clonedMaterial.emissive = mesh.material.emissive.clone();
                                clonedMaterial.emissiveIntensity = mesh.material.emissiveIntensity;
                            }
                            if (mesh.material.map) clonedMaterial.map = mesh.material.map;
                            originalMaterials.set(mesh.uuid, clonedMaterial);
                            mesh.castShadow = true;
                            mesh.receiveShadow = true;
                            mesh.material.emissiveIntensity = 0;
                            mesh.geometry.computeVertexNormals();
                            if (!mesh.geometry.boundingBox) mesh.geometry.computeBoundingBox();
                            //console.log(`Mesh: ${mesh.name}, Geometry: ${mesh.geometry.type}, Material: ${mesh.material.name}`);
                            // Принудительно включаем raycast
                            mesh.raycast = THREE.Mesh.prototype.raycast;
                        }
                    });
                    _objects.push(child);
                }
            });

            console.log('initCube: Objects filled, length=', _objects.length);
            _objects.forEach((obj, i) => {
                console.log(`Object ${i}: ${obj.name}, Children: ${obj.children.length}`);
            });

            const body = new CANNON.Body({
                mass: 1,
                position: new CANNON.Vec3(0, 5, 0),
                shape: new CANNON.Box(new CANNON.Vec3(0.5, 0.5, 0.5))
            });
            world.addBody(body);
            bodies.push({ mesh: model, body });

            if (onLoadCallback) onLoadCallback();
        },
        undefined,
        (error) => {
            console.error("Ошибка загрузки модели:", error);
        }
    );
}

export function initCannon() {
    world = new CANNON.World();
    world.broadphase = new CANNON.NaiveBroadphase();
    world.solver.iterations = 10;
    const groundBody = new CANNON.Body({
        mass: 1,
        position: new CANNON.Vec3(0, 0, 0),
        shape: new CANNON.Plane(),
    });
    groundBody.quaternion.setFromEuler(-Math.PI / 2, 0, 0);
    world.addBody(groundBody);
}

export function getCubesInLayer(normal, clickedObject) {
    const layerCubes = [];
    const threshold = 0.9;

    const clickedPos = new THREE.Vector3();
    clickedObject.getWorldPosition(clickedPos);

    const axis = Math.abs(normal.x) > threshold ? 'x' :
                 Math.abs(normal.y) > threshold ? 'y' : 'z';

    let layerCoord = Math.round(clickedPos[axis]);

    _objects.forEach(cube => {
        const cubePos = new THREE.Vector3();
        cube.getWorldPosition(cubePos);
        if (Math.abs(cubePos[axis] - layerCoord) < 0.1) {
            layerCubes.push(cube);
        }
    });

    console.log(`Слой по оси: ${axis}, координата: ${layerCoord}, кубиков: ${layerCubes.length}`);
    return { cubes: layerCubes };
}

export function checkFpsHit(){
    if (CurrentActiveCam !== 'player') return null;
    raycaster.setFromCamera(center, camera);
    return raycaster.intersectObjects(_objects, true)[0] || null        
}

export function rotateLayer(object, normal, isCounterclockwise = false) {
    return new Promise((resolve) => {
        if (isRotating || !object.parent || !normal.lengthSq()) {
            console.log('rotateLayer: blocked', { isRotating, hasParent: !!object.parent, normalLength: normal.lengthSq() });
            resolve();
            return;
        }
        console.log('Вращение🔃: ', {
            object: object.name,
            normal: { x: normal.x, y: normal.y, z: normal.z },
            camMode: CurrentActiveCam,
            direction: isCounterclockwise ? 'против часовой' : 'по часовой'
        });

        const layerData = getCubesInLayer(normal, object);
        cubesToRotate = layerData.cubes;

        console.log('rotateLayer: cubes to rotate=', cubesToRotate.length);
        if (cubesToRotate.length === 0) {
            console.log('rotateLayer: no cubes to rotate');
            resolve();
            return;
        }

        if (arrowHelper) {
            scene.remove(arrowHelper);
            arrowHelper = null;
        }
        progressArrows.forEach(arrow => scene.remove(arrow));
        progressArrows = [];

        rotationGroup = new THREE.Group();
        const centerPoint = new THREE.Vector3();
        cubesToRotate.forEach(cube => {
            const pos = new THREE.Vector3();
            cube.getWorldPosition(pos);
            centerPoint.add(pos);
        });
        centerPoint.divideScalar(cubesToRotate.length);

        rotationGroup.position.copy(centerPoint);
        scene.add(rotationGroup);

        cubesToRotate.forEach(cube => {
            const pos = new THREE.Vector3();
            cube.getWorldPosition(pos);
            cube.position.copy(pos.sub(centerPoint));
            scene.remove(cube);
            rotationGroup.add(cube);
        });

        rotationAxis.copy(normal).normalize();
        isRotating = true;

        updateProgressArrows(0);
        arrowHelper = new THREE.ArrowHelper(rotationAxis, rotationGroup.position, 2, 0xff0000);
        scene.add(arrowHelper);

        const targetAngle = isCounterclockwise ? -Math.PI / 2 : Math.PI / 2;
        const duration = 300;
        const startTime = performance.now();

        function animateRotation(currentTime) {
            if (!rotationGroup) {
                resolve();
                return;
            }
            const elapsed = currentTime - startTime;
            const progress = Math.min(elapsed / duration, 1);
            const angle = targetAngle * progress;

            rotationGroup.rotation.set(0, 0, 0);
            rotationGroup.rotateOnAxis(rotationAxis, angle);

            if (progress < 1) {
                requestAnimationFrame(animateRotation);
            } else {
                finishRotation();
                resolve();
            }
        }

        requestAnimationFrame(animateRotation);
    });
}

function updateProgressArrows(currentAngle) {
    progressArrows.forEach(arrow => scene.remove(arrow));
    progressArrows = [];

    const progress = Math.min(Math.abs(currentAngle) / (Math.PI / 2), 1);
    const startColor = new THREE.Color(0xff0000);
    const endColor = new THREE.Color(0x00ff00);
    const arrowColor = startColor.clone().lerp(endColor, progress);

    const arrowLength = 2 + progress * 1;
    const arrow1 = new THREE.ArrowHelper(rotationAxis, rotationGroup.position, arrowLength, arrowColor.getHex(), 0.3, 0.1);
    scene.add(arrow1);
    progressArrows.push(arrow1);

    const arrow2 = new THREE.ArrowHelper(rotationAxis.clone().negate(), rotationGroup.position, arrowLength, arrowColor.getHex(), 0.3, 0.1);
    scene.add(arrow2);
    progressArrows.push(arrow2);
}

function finishRotation() {
    if (!rotationGroup) return;

    cubesToRotate.forEach(cube => {
        cube.traverse(child => {
            if (child.isMesh && originalMaterials.has(child.uuid)) {
                child.material = originalMaterials.get(child.uuid).clone();
                child.material.needsUpdate = true;
                child.geometry.computeVertexNormals();
                if (child.material.emissive) {
                    child.material.emissiveIntensity = 0;
                }
            }
        });
    });

    const tempContainer = new THREE.Group();
    scene.add(tempContainer);
    tempContainer.position.copy(rotationGroup.position);
    tempContainer.quaternion.copy(rotationGroup.quaternion);

    while (rotationGroup.children.length > 0) {
        const cube = rotationGroup.children[0];
        const originalPos = new THREE.Vector3().copy(cube.position);
        rotationGroup.remove(cube);
        tempContainer.add(cube);
        cube.position.copy(originalPos);
    }

    while (tempContainer.children.length > 0) {
        const cube = tempContainer.children[0];
        const worldPos = new THREE.Vector3();
        cube.getWorldPosition(worldPos);
        const worldQuater = cube.getWorldQuaternion(new THREE.Quaternion());

        worldPos.x = Math.round(worldPos.x * 1000) / 1000;
        worldPos.y = Math.round(worldPos.y * 1000) / 1000;
        worldPos.z = Math.round(worldPos.z * 1000) / 1000;
        worldQuater.x = Math.round(worldQuater.x * 1000) / 1000;
        worldQuater.y = Math.round(worldQuater.y * 1000) / 1000;
        worldQuater.z = Math.round(worldQuater.z * 1000) / 1000;
        worldQuater.w = Math.round(worldQuater.w * 1000) / 1000;

        tempContainer.remove(cube);
        scene.attach(cube);
        cube.position.copy(worldPos);
        cube.quaternion.copy(worldQuater);
    }

    scene.remove(tempContainer);
    if (arrowHelper) {
        scene.remove(arrowHelper);
        arrowHelper = null;
    }
    progressArrows.forEach(arrow => scene.remove(arrow));
    progressArrows = [];
    scene.remove(rotationGroup);
    isRotating = false;
    cubesToRotate = [];
    rotationGroup = null;
}

export async function scrambleCube(numMoves = 20){
    if (isRotating){
        console.warn(`Перемешивание не может быть выполнено, т.к сейчас кубик вращается`);
        return;
    }

    const axes = [
        new THREE.Vector3(1, 0, 0),
        new THREE.Vector3(0, 1, 0),
        new THREE.Vector3(0, 0, 1)
    ];

    for (let i = 0; i < numMoves; i++){
        const cube = _objects[Math.floor(Math.random() * _objects.length)];
        const axis = axes[Math.floor(Math.random() * axes.length)];
        const isCounterclockwise = Math.random() > 0.5;

        console.log(`Перемешивание: движение ${i+1}/${numMoves}: cube=${cube.name}, axis=${axis.toArray()}, direction=${isCounterclockwise ? 'против часовой' : 'по часовой'}`)
        await rotateLayer(cube, axis, isCounterclockwise);
    }
    console.log(`Перемешивание куба завершено-успешно`)
}

// Вспомогательная функция для поиска кубика по позиции
function findCubeByPosition(x, y, z){
    const threshold = 0.1
    return _objects.find(cube => {
        const pos = new THREE.Vector3();
        cube.getWorldPosition(pos);
        return Math.abs(pos.x - x) < threshold &&
               Math.abs(pos.y - y) < threshold &&
               Math.abs(pos.z - z) < threshold;        
    });
}

// Вспомогательная функция для определения цвета грани кубика
function getFaceColor(cube, normal){
    if (!cube) return null;
    const threshold = 0.9;
    const worldNormal = normal.clone().applyMatrix4(cube.matrixWorld).sub(cube.getWorldPosition(new THREE.Vector3())).normalize();
    const absNormal = new THREE.Vector3(Math.abs(worldNormal.x), Math.abs(worldNormal.y), Math.abs(worldNormal.z));
    let faceColor;
    if (absNormal.x > threshold){
        faceColor = worldNormal.x > 0 ? 0xff0000 : 0xffa500; // Красная или оранжевая
    } else if (absNormal.y > threshold){
        faceColor = worldNormal.y > 0 ? 0xffffff : 0xffff00; // Белая или желтая
    } else if (absNormal.z > threshold){
        faceColor = worldNormal.z > 0 ? 0x00ff00 : 0x0000ff; // Зелёная или синяя
    }
    return faceColor;
}

// функция для получения состояния кубика
function getCubeState(){
    const state = {
        centers: [],
        egdes: [],
        corners: []
    };

    // Определяем центры граней
    const centerCubes = _objects.filter(cube => cube.name.includes("CENTER"));
    centerCubes.forEach(cube => {
        const pos = new THREE.Vector3();
        cube.getWorldPosition(pos);
        const axis = Math.abs(pos.x) > 1.9 ? 'x' : Math.abs(pos.y) > 1.9 ? 'y' : 'z';
        const coord = Math.round(pos[axis]);
        const normal = new THREE.Vector3();
        normal[axis] = coord > 0 ? 1 : -1;
        const color = getFaceColor(cube, normal);
        state.centers[axis + coord] = { cube, color, normal };
    });

    // Определяем рёбра
    const edgeCubes = _objects.filter(cube => !cube.name.includes("CENTER") && cube.name.match(/^[A-Z][0-9]_[A-Z]{2}\d{3}$/));
    edgeCubes.forEach(cube => {
        const pos = new THREE.Vector3();
        cube.getWorldPosition(pos);
        pos.x = Math.round(pos.x * 100) / 100;
        pos.y = Math.round(pos.y * 100) / 100;
        pos.z = Math.round(pos.z * 100) / 100;
        const key = `${pos.x},${pos.y},${pos.z}`;
        const normals = [
            new THREE.Vector3(1, 0, 0), new THREE.Vector3(-1, 0, 0),
            new THREE.Vector3(0, 1, 0), new THREE.Vector3(0, -1, 0),
            new THREE.Vector3(0, 0, 1), new THREE.Vector3(0, 0, -1)
        ];
        const colors = normals.map(normal => getFaceColor(cube, normal)).filter(color => color);
        state.edges[key] = { cube, colors, position: pos };
    });

    // Определяем углы
    const cornerCubes = _objects.filter(cube => !cube.name.includes("CENTER") && cube.name.match(/^[A-Z][0-9]_[A-Z]{3}\d{3}$/));
    cornerCubes.forEach(cube => {
        const pos = new THREE.Vector3();
        cube.getWorldPosition(pos);
        pos.x = Math.round(pos.x * 100) / 100;
        pos.y = Math.round(pos.y * 100) / 100;
        pos.z = Math.round(pos.z * 100) / 100;
        const key = `${pos.x},${pos.y},${pos.z}`;
        const normals = [
            new THREE.Vector3(1, 0, 0), new THREE.Vector3(-1, 0, 0),
            new THREE.Vector3(0, 1, 0), new THREE.Vector3(0, -1, 0),
            new THREE.Vector3(0, 0, 1), new THREE.Vector3(0, 0, -1)
        ];
        const colors = normals.map(normal => getFaceColor(cube, normal)).filter(color => color);
        state.corners[key] = { cube, colors, position: pos };
    });

    return state;   
}

// Функция для выполнения стандартных ходов (U, D, L, R, F, B)
async function performMove(face, isCounterclockwise = false) {
    const axes = {
        U: { normal: new THREE.Vector3(0, 1, 0), coord: 2 }, // Верх (белый)
        D: { normal: new THREE.Vector3(0, -1, 0), coord: -2 }, // Низ (жёлтый)
        L: { normal: new THREE.Vector3(-1, 0, 0), coord: -2 }, // Лево (оранжевый)
        R: { normal: new THREE.Vector3(1, 0, 0), coord: 2 }, // Право (красный)
        F: { normal: new THREE.Vector3(0, 0, 1), coord: 2 }, // Фронт (зелёный)
        B: { normal: new THREE.Vector3(0, 0, -1), coord: -2 } // Зад (синий)
    };
    const { normal, coord } = axes[face];
    const cube = findCubeByPosition(
        face === 'L' || face === 'R' ? coord : 0,
        face === 'U' || face === 'D' ? coord : 0,
        face === 'F' || face === 'B' ? coord : 0
    );
    if (cube) {
        console.log(`Выполняется ход ${face}${isCounterclockwise ? "'" : ""}`);
        await rotateLayer(cube, normal, isCounterclockwise);
    } else {
        console.warn(`Кубик для хода ${face} не найден`);
    }
}

// Функция авто-сборки кубика
export async function solveCube() {
    if (isRotating) {
        console.warn(`Сборка не может быть выполнена, т.к сейчас кубик вращается`);
        return;
    }

    console.log('Начата сборка кубика...');
    const state = getCubeState();

    // Шаг 1: Формирование креста на нижней грани (жёлтая)
    console.log('Шаг 1: Формирование жёлтого креста');
    const yellowCenter = state.centers['y-2'];
    if (!yellowCenter || yellowCenter.color !== 0xffff00) {
        console.warn('Жёлтый центр не найден или не жёлтый');
        return;
    }
    const edgePositions = [
        { pos: [0, -2, 2], colors: [0xffff00, 0x00ff00] }, // Жёлто-зелёное ребро
        { pos: [0, -2, -2], colors: [0xffff00, 0x0000ff] }, // Жёлто-синее
        { pos: [2, -2, 0], colors: [0xffff00, 0xff0000] }, // Жёлто-красное
        { pos: [-2, -2, 0], colors: [0xffff00, 0xffa500] } // Жёлто-оранжевое
    ];

    for (const { pos, colors } of edgePositions) {
        const key = `${pos[0]},${pos[1]},${pos[2]}`;
        const edge = Object.values(state.edges).find(e =>
            e.position.x === pos[0] && e.position.y === pos[1] && e.position.z === pos[2]
        );
        if (!edge) {
            console.warn(`Ребро на позиции ${key} не найдено`);
            continue;
        }
        if (edge.colors.includes(0xffff00)) {
            // Ребро уже на нижней грани, проверяем ориентацию
            const yellowNormal = new THREE.Vector3(0, -1, 0);
            if (getFaceColor(edge.cube, yellowNormal) !== 0xffff00) {
                // Поворачиваем фронтальную грань, чтобы жёлтый был внизу
                const otherColor = edge.colors.find(c => c !== 0xffff00);
                let face;
                if (otherColor === 0x00ff00) face = 'F';
                else if (otherColor === 0x0000ff) face = 'B';
                else if (otherColor === 0xff0000) face = 'R';
                else if (otherColor === 0xffa500) face = 'L';
                await performMove(face);
                await performMove(face);
            }
        } else {
            // Ищем ребро с жёлтым цветом
            const yellowEdge = Object.values(state.edges).find(e => e.colors.includes(0xffff00));
            if (!yellowEdge) {
                console.warn('Ребро с жёлтым цветом не найдено');
                continue;
            }
            // Простой алгоритм: поворачиваем верхнюю грань, пока ребро не попадёт в нужную позицию
            for (let i = 0; i < 4; i++) {
                if (yellowEdge.position.y > 1.9) {
                    const otherColor = yellowEdge.colors.find(c => c !== 0xffff00);
                    let targetFace;
                    if (otherColor === 0x00ff00) targetFace = 'F';
                    else if (otherColor === 0x0000ff) targetFace = 'B';
                    else if (otherColor === 0xff0000) targetFace = 'R';
                    else if (otherColor === 0xffa500) targetFace = 'L';
                    await performMove('U');
                    await performMove(targetFace);
                    await performMove('U', true);
                    await performMove(targetFace);
                    await performMove(targetFace);
                    break;
                }
                await performMove('U');
                // Обновляем состояние
                const newState = getCubeState();
                yellowEdge.position = newState.edges[`${yellowEdge.position.x},${yellowEdge.position.y},${yellowEdge.position.z}`].position;
            }
        }
    }

    // Шаг 2: Установка углов нижнего слоя
    console.log('Шаг 2: Установка углов нижнего слоя');
    const cornerPositions = [
        { pos: [2, -2, 2], colors: [0xffff00, 0xff0000, 0x00ff00] }, // Жёлто-красно-зелёный
        { pos: [-2, -2, 2], colors: [0xffff00, 0xffa500, 0x00ff00] }, // Жёлто-оранжево-зелёный
        { pos: [2, -2, -2], colors: [0xffff00, 0xff0000, 0x0000ff] }, // Жёлто-красно-синий
        { pos: [-2, -2, -2], colors: [0xffff00, 0xffa500, 0x0000ff] } // Жёлто-оранжево-синий
    ];

    for (const { pos, colors } of cornerPositions) {
        const key = `${pos[0]},${pos[1]},${pos[2]}`;
        const corner = state.corners[key];
        if (!corner) {
            // Ищем угол с нужными цветами
            const targetCorner = Object.values(state.corners).find(c =>
                colors.every(color => c.colors.includes(color))
            );
            if (!targetCorner) {
                console.warn(`Угол с цветами ${colors.map(c => c.toString(16))} не найден`);
                continue;
            }
            // Алгоритм для углов: U R U' R' или U' L' U L
            for (let i = 0; i < 8; i++) {
                if (targetCorner.position.y > 1.9) {
                    const isRight = targetCorner.position.x > 0;
                    await performMove('U', !isRight);
                    await performMove(isRight ? 'R' : 'L', !isRight);
                    await performMove('U', isRight);
                    await performMove(isRight ? 'R' : 'L', isRight);
                    // Обновляем состояние
                    const newState = getCubeState();
                    targetCorner.position = newState.corners[`${targetCorner.position.x},${targetCorner.position.y},${targetCorner.position.z}`].position;
                } else if (targetCorner.position.y < -1.9) {
                    // Проверяем ориентацию
                    const yellowNormal = new THREE.Vector3(0, -1, 0);
                    if (getFaceColor(targetCorner.cube, yellowNormal) !== 0xffff00) {
                        const isRight = targetCorner.position.x > 0;
                        await performMove(isRight ? 'R' : 'L', !isRight);
                        await performMove('U', isRight);
                        await performMove(isRight ? 'R' : 'L', isRight);
                        await performMove('U', !isRight);
                    } else {
                        break;
                    }
                } else {
                    await performMove('U');
                    const newState = getCubeState();
                    targetCorner.position = newState.corners[`${targetCorner.position.x},${targetCorner.position.y},${targetCorner.position.z}`].position;
                }
            }
        }
    }

    // Шаг 3: Установка рёбер среднего слоя
    console.log('Шаг 3: Установка рёбер среднего слоя');
    const middleEdgePositions = [
        { pos: [2, 0, 2], colors: [0xff0000, 0x00ff00] }, // Красно-зелёное
        { pos: [-2, 0, 2], colors: [0xffa500, 0x00ff00] }, // Оранжево-зелёное
        { pos: [2, 0, -2], colors: [0xff0000, 0x0000ff] }, // Красно-синее
        { pos: [-2, 0, -2], colors: [0xffa500, 0x0000ff] } // Оранжево-синее
    ];

    for (const { pos, colors } of middleEdgePositions) {
        const key = `${pos[0]},${pos[1]},${pos[2]}`;
        const edge = state.edges[key];
        if (!edge || !edge.colors.every(c => colors.includes(c))) {
            const targetEdge = Object.values(state.edges).find(e =>
                colors.every(color => e.colors.includes(color))
            );
            if (!targetEdge) {
