        cube.getWorldPosition(pos);
        // Округляем координаты с учётом возможных неточностей
        pos.x = Math.round(pos.x * 100) / 100;
        pos.y = Math.round(pos.y * 100) / 100;
        pos.z = Math.round(pos.z * 100) / 100;

        // Определяем ось и координату
        const threshold = 1.9;
        let axis, coord;
        if (Math.abs(pos.x) > threshold) {
            axis = 'x';
            coord = Math.round(pos.x);
        } else if (Math.abs(pos.y) > threshold) {
            axis = 'y';
            coord = Math.round(pos.y);
        } else if (Math.abs(pos.z) > threshold) {
            axis = 'z';
            coord = Math.round(pos.z);
        } else {
            console.warn(`Центральный кубик ${cube.name} имеет некорректную позицию: [${pos.x}, ${pos.y}, ${pos.z}]`);
            return; // Пропускаем кубик с некорректной позицией
        }

        // Проверяем, что coord имеет ожидаемые значения (±2)
        if (Math.abs(coord) !== 2) {
            console.warn(`Центральный кубик ${cube.name} имеет неожиданную координату ${coord} по оси ${axis}`);
            return;
        }

        const normal = new THREE.Vector3();
        normal[axis] = coord > 0 ? 1 : -1;
        const color = getFaceColor(cube, normal);
        const key = `${axis}${coord > 0 ? '2' : '-2'}`; // Формируем ключ, например, 'x2', 'y-2'
        state.centers[key] = { cube, color, normal };
        console.log(`Центр ${cube.name}: key=${key}, pos=[${pos.x}, ${pos.y}, ${pos.z}], color=${color?.toString(16)}`);
    });

    // Определяем рёбра
    const edgeCubes = _objects.filter(cube => !cube.name.includes("CENTER") && cube.name.match(/^[A-Z][0-9]_[A-Z]{2}\d{3}$/));
    edgeCubes.forEach(cube => {
        const pos = new THREE.Vector3();
        cube.getWorldPosition(pos);
        pos.x = Math.round(pos.x * 100) / 100;
        pos.y = Math.round(pos.y * 100) / 100;
        pos.z = Math.round(pos.z * 100) / 100;
        const key = `${pos.x},${pos.y},${pos.z}`;
        const normals = [
            new THREE.Vector3(1, 0, 0), new THREE.Vector3(-1, 0, 0),
            new THREE.Vector3(0, 1, 0), new THREE.Vector3(0, -1, 0),
            new THREE.Vector3(0, 0, 1), new THREE.Vector3(0, 0, -1)
        ];
        const colors = normals.map(normal => getFaceColor(cube, normal)).filter(color => color);
        state.edges[key] = { cube, colors, position: pos };
    });

    // Определяем углы
    const cornerCubes = _objects.filter(cube => !cube.name.includes("CENTER") && cube.name.match(/^[A-Z][0-9]_[A-Z]{3}\d{3}$/));
    cornerCubes.forEach(cube => {
        const pos = new THREE.Vector3();
        cube.getWorldPosition(pos);
        pos.x = Math.round(pos.x * 100) / 100;
        pos.y = Math.round(pos.y * 100) / 100;
        pos.z = Math.round(pos.z * 100) / 100;
        const key = `${pos.x},${pos.y},${pos.z}`;
        const normals = [
            new THREE.Vector3(1, 0, 0), new THREE.Vector3(-1, 0, 0),
            new THREE.Vector3(0, 1, 0), new THREE.Vector3(0, -1, 0),
            new THREE.Vector3(0, 0, 1), new THREE.Vector3(0, 0, -1)
        ];
        const colors = normals.map(normal => getFaceColor(cube, normal)).filter(color => color);
        state.corners[key] = { cube, colors, position: pos };
    });

    return state;
}
