#### Проверка функции `getFaceColor`
Поскольку цвета центров могут определяться некорректно из-за неправильных позиций, проверь функцию `getFaceColor`:

```javascript
function getFaceColor(cube, normal) {
    if (!cube) return null;
    const worldNormal = normal.clone().applyMatrix4(cube.matrixWorld).sub(cube.getWorldPosition(new THREE.Vector3())).normalize();
    const absNormal = new THREE.Vector3(Math.abs(worldNormal.x), Math.abs(worldNormal.y), Math.abs(worldNormal.z));
    const threshold = 0.9;
    let faceColor;
    if (absNormal.x > threshold) {
        faceColor = worldNormal.x > 0 ? 0xff0000 : 0xffa500; // Красный или оранжевый
    } else if (absNormal.y > threshold) {
        faceColor = worldNormal.y > 0 ? 0xffffff : 0xffff00; // Белый или жёлтый
    } else if (absNormal.z > threshold) {
        faceColor = worldNormal.z > 0 ? 0x00ff00 : 0x0000ff; // Зелёный или синий
    }
    if (!faceColor) {
        console.warn(`Цвет не определён для кубика ${cube.name}, нормаль=[${worldNormal.x.toFixed(2)}, ${worldNormal.y.toFixed(2)}, ${worldNormal.z.toFixed(2)}]`);
    }
    return faceColor;
}
```

