       { pos: [0, -2, 2], colors: [0xffff00, 0x00ff00] }, // Жёлто-зелёное
       { pos: [0, -2, -2], colors: [0xffff00, 0x0000ff] }, // Жёлто-синее
       { pos: [2, -2, 0], colors: [0xffff00, 0xff0000] }, // Жёлто-красное
