Поскольку `getCubeState` использует `getFaceColor` для определения цветов рёбер, убедимся, что нормали корректно преобразуются после `scrambleCube`. Добавьте отладку в `getFaceColor`:

```javascript
function getFaceColor(cube, normal) {
    if (!cube) return null;
    const threshold = 0.9;
    const worldNormal = normal.clone().applyMatrix4(cube.matrixWorld).sub(cube.getWorldPosition(new THREE.Vector3())).normalize();
    const absNormal = new THREE.Vector3(Math.abs(worldNormal.x), Math.abs(worldNormal.y), Math.abs(worldNormal.z));
    let faceColor;
    if (absNormal.x > threshold) {
        faceColor = worldNormal.x > 0 ? 0xff0000 : 0xffa500; // Красная или оранжевая
    } else if (absNormal.y > threshold) {
        faceColor = worldNormal.y > 0 ? 0xffffff : 0xffff00; // Белая или жёлтая
    } else if (absNormal.z > threshold) {
        faceColor = worldNormal.z > 0 ? 0x00ff00 : 0x0000ff; // Зелёная или синяя
    }
    console.log(`getFaceColor для ${cube.name}: inputNormal=[${normal.x}, ${normal.y}, ${normal.z}], worldNormal=[${worldNormal.x.toFixed(2)}, ${worldNormal.y.toFixed(2)}, ${worldNormal.z.toFixed(2)}], color=${faceColor?.toString(16)}`);
    return faceColor;
}
```

**Изменения**:
