            new THREE.Vector3(0, 0, 1), new THREE.Vector3(0, 0, -1)
        ];
        const colors = normals.map(normal => getFaceColor(cube, normal)).filter(color => color);
        if (colors.length !== 2) {
            console.warn(`Ребро ${cube.name} имеет ${colors.length} цветов вместо 2: ${colors.map(c => c.toString(16))}`);
        }
        state.edges[key] = { cube, colors, position: pos };
        console.log(`Ребро ${cube.name}: позиция=[${pos.x}, ${pos.y}, ${pos.z}], цвета=${colors.map(c => c.toString(16))}`);
    });

    const cornerCubes = _objects.filter(cube => !cube.name.includes("CENTER") && cube.name.match(/^[A-Z][0-9]_[A-Z]{3}\d{3}$/));
    cornerCubes.forEach(cube => {
        const pos = new THREE.Vector3();
        cube.getWorldPosition(pos);
        pos.x = Math.round(pos.x * 100) / 100;
        pos.y = Math.round(pos.y * 100) / 100;
        pos.z = Math.round(pos.z * 100) / 100;
        const key = `${pos.x},${pos.y},${pos.z}`;
        const normals = [
            new THREE.Vector3(1, 0, 0), new THREE.Vector3(-1, 0, 0),
            new THREE.Vector3(0, 1, 0), new THREE.Vector3(0, -1, 0),
            new THREE.Vector3(0, 0, 1), new THREE.Vector3(0, 0, -1)
        ];
        const colors = normals.map(normal => getFaceColor(cube, normal)).filter(color => color);
        if (colors.length !== 3) {
            console.warn(`Угол ${cube.name} имеет ${colors.length} цветов вместо 3: ${colors.map(c => c.toString(16))}`);
        }
        state.corners[key] = { cube, colors, position: pos };
        console.log(`Угол ${cube.name}: позиция=[${pos.x}, ${pos.y}, ${pos.z}], цвета=${colors.map(c => c.toString(16))}`);
    });

    return state;
}
```

**Изменения**:
- В `getFaceColor` для рёбер используются только цвета, соответствующие имени кубика (например, `WR` в `R2_WR002` означает белый и красный).
- Добавлена проверка в `getCubeState`, чтобы логировать предупреждение, если ребро имеет не два цвета, а угол — не три.
- Нормали фильтруются по ожидаемым цветам, чтобы исключить лишние наклейки.

#### Шаг 2: Исправление `solveCube`
Обновим `solveCube`, чтобы корректно обрабатывать рёбра и избежать ошибки с `undefined`:

```javascript
