#### 3. Проверка `cubeInteraction.js`
Код триггеров выглядит корректно, но убедимся, что `cubeSize` соответствует кубу (диагональ ~6.12 для позиций ±2.04). Код остаётся без изменений, но для отладки оставим `zoneMaterial.visible = true`.

```javascript
export function createTriggerZones(cubeSize = 6.12) {
    const zones = [];
    const halfSize = cubeSize / 2;
    const smallCubeSize = cubeSize / 3;
    const layerPositions = [smallCubeSize, 0, -smallCubeSize];
    const zoneSize = smallCubeSize * 0.7;
    const zoneThickness = smallCubeSize * 0.1;
    const outwardOffset = zoneThickness / 2;

    const zoneMaterial = new THREE.MeshBasicMaterial({
        color: 0x00ffff,
        wireframe: true,
        transparent: true,
        opacity: 0.5,
        visible: true, // Для отладки
        side: THREE.DoubleSide
    });

    const edges = [
        { fixedX: halfSize, fixedZ: halfSize, edgeAxis: 'y', outwardDir: new THREE.Vector3(1, 0, 1), triggeredFace: 'right' },
        { fixedX: halfSize, fixedZ: -halfSize, edgeAxis: 'y', outwardDir: new THREE.Vector3(1, 0, -1), triggeredFace: 'right' },
        { fixedX: -halfSize, fixedZ: halfSize, edgeAxis: 'y', outwardDir: new THREE.Vector3(-1, 0, 1), triggeredFace: 'left' },
        { fixedX: -halfSize, fixedZ: -halfSize, edgeAxis: 'y', outwardDir: new THREE.Vector3(-1, 0, -1), triggeredFace: 'left' },
        { fixedY: halfSize, fixedZ: halfSize, edgeAxis: 'x', outwardDir: new THREE.Vector3(0, 1, 1), triggeredFace: 'up' },
        { fixedY: -halfSize, fixedZ: halfSize, edgeAxis: 'x', outwardDir: new THREE.Vector3(0, -1, 1), triggeredFace: 'down' },
        { fixedY: halfSize, fixedZ: -halfSize, edgeAxis: 'x', outwardDir: new THREE.Vector3(0, 1, -1), triggeredFace: 'up' },
        { fixedY: -halfSize, fixedZ: -halfSize, edgeAxis: 'x', outwardDir: new THREE.Vector3(0, -1, -1), triggeredFace: 'down' },
        { fixedX: halfSize, fixedY: halfSize, edgeAxis: 'z', outwardDir: new THREE.Vector3(1, 1, 0), triggeredFace: 'right' },
        { fixedX: -halfSize, fixedY: halfSize, edgeAxis: 'z', outwardDir: new THREE.Vector3(-1, 1, 0), triggeredFace: 'left' },
        { fixedX: halfSize, fixedY: -halfSize, edgeAxis: 'z', outwardDir: new THREE.Vector3(1, -1, 0), triggeredFace: 'right' },
        { fixedX: -halfSize, fixedY: -halfSize, edgeAxis: 'z', outwardDir: new THREE.Vector3(-1, -1, 0), triggeredFace: 'left' },
    ];

    const zoneGeometry = new THREE.BoxGeometry(zoneSize, zoneSize, zoneThickness);

    edges.forEach(edge => {
        const outwardVector = edge.outwardDir.clone().normalize();
        layerPositions.forEach((layerPos, index) => {
            const zone = new THREE.Mesh(zoneGeometry, zoneMaterial);
            const yOffset = 0;
            const position = new THREE.Vector3();
            if (edge.edgeAxis === 'y') {
                position.set(edge.fixedX, layerPos + yOffset, edge.fixedZ);
            } else if (edge.edgeAxis === 'x') {
                position.set(layerPos, edge.fixedY + yOffset, edge.fixedZ);
            } else if (edge.edgeAxis === 'z') {
                position.set(edge.fixedX, edge.fixedY + yOffset, layerPos);
            }
            position.add(outwardVector.clone().multiplyScalar(zoneThickness / 2 + outwardOffset));
            zone.position.copy(position);

            zone.lookAt(zone.position.clone().add(outwardVector));
            zone.rotateOnAxis(new THREE.Vector3(0, 1, 0), Math.PI);

            zone.userData = {
                isTriggerZone: true,
                triggeredFace: edge.triggeredFace,
                layerIndex: index,
            };

            zones.push(zone);
        });
    });

    return zones;
}
