            Rotation: [${rotDeg.x}, ${rotDeg.y}, ${rotDeg.z}]°
        `;

        const deltaTime = 1/60;
        renderer.render(scene, camera);
        stats.update();
    } catch (err) {
        console.error('Ошибка в игровом цикле: ', err);
    }
}

