Добавим смещение `extrudeOffset` вдоль нормали грани. Сначала определим нормаль грани, а затем сместим позиции стрелок. Вот обновлённый фрагмент:

```javascript
function showArrows(cube) {
    arrows.forEach(arrow => scene.remove(arrow));
    arrows = [];

    const cubeSize = 6.12 / 3;
    const position = cube.getWorldPosition(new THREE.Vector3());
    const offset = cubeSize * 0.3;

    const objects = getObjects();
    const index = objects.indexOf(cube);
    const row = Math.floor(index / 3) + 1;
    const col = (index % 3) + 1;

    console.log(`Selected cube: ${cube.name}, Position: (${row}, ${col}), Index: ${index}`);
    console.log(`Cube world position: [${position.x.toFixed(2)}, ${position.y.toFixed(2)}, ${position.z.toFixed(2)}]`);

    // Определяем нормаль грани
    const normal = new THREE.Vector3();
    cube.getWorldDirection(normal); // Нормаль направлена от центра куба наружу
    console.log(`Face normal: ${normal.toArray()}`);

    // Смещение для "выдавливания" стрелок за куб
    const extrudeOffset = cubeSize * 0.5; // Например, 0.5 от размера кубика
    const extrudeVector = normal.clone().multiplyScalar(extrudeOffset);

    const rotationAngle = Math.PI / 2; // Поворот на 90 градусов

    const directions = [
        { dir: new THREE.Vector3(0, 0, 1), pos: new THREE.Vector3(0, 0, offset), color: 0xff0000 }, // ⬆
        { dir: new THREE.Vector3(0, 0, -1), pos: new THREE.Vector3(0, 0, -offset), color: 0x00ff00 }, // ⬇
        { dir: new THREE.Vector3(-1, 0, 0), pos: new THREE.Vector3(-offset, 0, 0), color: 0x0000ff }, // ⬅
        { dir: new THREE.Vector3(1, 0, 0), pos: new THREE.Vector3(offset, 0, 0), color: 0xffff00 } // ➡
    ];

    directions.forEach(({ dir, pos, color }, idx) => {
        const rotatedPos = pos.clone().applyAxisAngle(new THREE.Vector3(0, 1, 0), rotationAngle);
        // Смещаем позицию вдоль нормали
        const arrowPos = position.clone().add(rotatedPos).add(extrudeVector);

        const rotatedDir = dir.clone().applyAxisAngle(new THREE.Vector3(0, 1, 0), rotationAngle);

        console.log(`Creating arrow ${idx + 1}: dir=${rotatedDir.toArray()}, pos=${arrowPos.toArray()}, color=${color.toString(16)}`);
        const arrow = createArrow(arrowPos, rotatedDir, color);
        arrows.push(arrow);
    });

    if (row === 2 && col === 2) {
        const rotateCWPosBase = new THREE.Vector3(offset, 0, offset);
        const rotateCWPos = position.clone()
            .add(rotateCWPosBase.applyAxisAngle(new THREE.Vector3(0, 1, 0), rotationAngle))
            .add(extrudeVector); // Добавляем смещение
        const rotateCW = createArrow(rotateCWPos, new THREE.Vector3(0, 1, 0), 0xff00ff, true);
        rotateCW.userData.clockwise = true;
        arrows.push(rotateCW);
        console.log(`Added CW arrow: pos=${rotateCWPos.toArray()}`);

        const rotateCCWPosBase = new THREE.Vector3(-offset, 0, -offset);
        const rotateCCWPos = position.clone()
            .add(rotateCCWPosBase.applyAxisAngle(new THREE.Vector3(0, 1, 0), rotationAngle))
            .add(extrudeVector); // Добавляем смещение
        const rotateCCW = createArrow(rotateCCWPos, new THREE.Vector3(0, -1, 0), 0x00ffff, true);
        rotateCCW.userData.clockwise = false;
        arrows.push(rotateCCW);
        console.log(`Added CCW arrow: pos=${rotateCCWPos.toArray()}`);
    }

    console.log(`Total arrows created: ${arrows.length}`);
}
```

### Что сделано
1. **Нормаль грани**: Использовал `cube.getWorldDirection(normal)` для получения нормали грани, которая указывает направление "наружу".
2. **Смещение**: Добавил `extrudeOffset = cubeSize * 0.5` (примерно 1.02) и сместил позиции стрелок вдоль нормали с помощью `extrudeVector`.
3. **Применение**: Все позиции стрелок (включая 🔄) теперь смещены на `extrudeVector`, что "выдавливает" их за пределы куба.

### Ожидаемый результат
- Стрелки сместятся вдоль нормали грани (в данном случае, вдоль оси X, так как грань зелёная, и нормаль, вероятно, `[1, 0, 0]`).
- Например, если позиция стрелки была `[0, 0, 0]`, то после смещения она станет `[1.02, 0, 0]` (при `extrudeOffset = 1.02`).
- Стрелки визуально окажутся снаружи куба, но всё ещё будут в плоскости грани, повернутой на 90 градусов.

### Как проверить
