    const arrow = new THREE.Mesh(arrowGeometry, arrowMaterial);
    arrow.position.copy(position);
    arrow.lookAt(position.clone().add(direction));
    arrow.rotateX(Math.PI); // Переворачиваем конус для правильного направления
    arrow.userData = { direction };
    if (isRotate) arrow.userData.isRotate = true;
    scene.add(arrow);
    return arrow;
}

