function createArrow(position, direction, color = 0x00ff00, isRotate = false) {
    let geometry;
    if (isRotate) {
        geometry = new THREE.SphereGeometry(0.2, 16, 16);
    } else {
        geometry = new THREE.ConeGeometry(0.3, 0.6, 8);
    }
    const material = new THREE.MeshBasicMaterial({ color });
    const arrow = new THREE.Mesh(geometry, material);
    arrow.position.copy(position);

    if (!isRotate) {
        // Переопределяем направления с учётом нового соответствия
        if (color === 0xff0000) {        // ↑ (красный) — вверх по X+ (соотвествие)        
            arrow.lookAt(position.clone().add(new THREE.Vector3(0, 1, 0))); // вверх
        } else if (color === 0x00ff00) { // ↓ (зелёный) — вниз по Y- (соотвествие)
            arrow.lookAt(position.clone().add(new THREE.Vector3(-1, 0, 0))); // вниз
        } else if (color === 0xffff00) { // ← (жёлтый) — вверх по Y+ (соотвествие)
            arrow.lookAt(position.clone().add(new THREE.Vector3(0, -1, 0))); // влево
        } else if (color === 0xff0000) { // → (синий) — вправо по X- (соотвествие)
            arrow.lookAt(position.clone().add(new THREE.Vector3(1, 0, 0)));  // вправо
        }
        arrow.rotateX(Math.PI); // Переворачиваем конус
    }
    arrow.userData = { direction };
    if (isRotate) {
        arrow.userData.isRotate = true;
    }
    scene.add(arrow);
    return arrow;
}

function showArrows(cube) {
    // Удаляем старые стрелки
    arrows.forEach(arrow => scene.remove(arrow));
    arrows = [];

    const cubeSize = 6.12 / 3;
    const position = cube.getWorldPosition(new THREE.Vector3());
    const offset = cubeSize * 0.5;

    // Определяем нормаль грани
    const normal = new THREE.Vector3();
    cube.getWorldDirection(normal); // Нормаль направлена от центра куба наружу
    console.log(`Face normal: ${normal.toArray()}`);

    // Смещение для "выдавливания" за грань
    const extrudeOffset = cubeSize * 0.7;
    const extrudeVector = normal.clone().multiplyScalar(extrudeOffset);

    // Определяем локальные оси грани (обнуляем относительно грани)
    const upVector = new THREE.Vector3(0, 1, 0).applyQuaternion(cube.getWorldQuaternion(new THREE.Quaternion()));
    const rightVector = new THREE.Vector3(1, 0, 0).applyQuaternion(cube.getWorldQuaternion(new THREE.Quaternion()));
    if (Math.abs(normal.dot(upVector)) > 0.9) {
        upVector.set(0, 0, 1).applyQuaternion(cube.getWorldQuaternion(new THREE.Quaternion())); // Если нормаль близка к Y, используем Z как вверх
    }
    rightVector.crossVectors(normal, upVector).normalize();

    // Стрелки для всех позиций (⬆⬇⬅➡)
    const directions = [
        { dir: rightVector.clone(), pos: upVector.clone().multiplyScalar(offset), color: 0xff0000 }, // ↑ (красный, вверх)
        { dir: rightVector.clone().negate(), pos: upVector.clone().negate().multiplyScalar(offset), color: 0x00ff00 }, // ↓ (зеленый, вниз)
        { dir: upVector.clone(), pos: rightVector.clone().negate().multiplyScalar(offset), color: 0x0000ff }, // → (синий, вправо)
        { dir: upVector.clone().negate(), pos: rightVector.clone().multiplyScalar(offset), color: 0xffff00 }, // ← (желтый, влево)
    ];

    directions.forEach(({ dir, pos, color }, idx) => {
        const arrowPos = position.clone().add(extrudeVector).add(pos);
        console.log(`Creating arrow ${idx + 1}: dir=${dir.toArray()}, pos=${arrowPos.toArray()}, color=${color.toString(16)}`);
        const arrow = createArrow(arrowPos, dir, color);
        arrows.push(arrow);
    });

    // Дополнительные стрелки 🔄 для центрального кубика (2,2)
    if (row === 2 && col === 2) {
        const rotateCWPos = position.clone().add(extrudeVector).add(upVector.clone().multiplyScalar(offset));
        const rotateCW = createArrow(rotateCWPos, normal.clone(), 0x000000, true); // Чёрный шар для 🔄 по часовой
        rotateCW.userData.clockwise = true;
        arrows.push(rotateCW);
        console.log(`Added CW arrow: pos=${rotateCWPos.toArray()}`);

        const rotateCCWPos = position.clone().add(extrudeVector).add(upVector.clone().negate().multiplyScalar(offset));
        const rotateCCW = createArrow(rotateCCWPos, normal.clone().negate(), 0x00ffff, true); // Бирюзовый шар для 🔄 против часовой
        rotateCCW.userData.clockwise = false;
        arrows.push(rotateCCW);
        console.log(`Added CCW arrow: pos=${rotateCCWPos.toArray()}`);
    }

    console.log(`Total arrows created: ${arrows.length}`);
}

