// Вспомогательная функция для поиска кубика по позиции
function findCubeByPosition(x, y, z) {
    const threshold = 0.1;
    return _objects.find(cube => {
        const pos = new THREE.Vector3();
        cube.getWorldPosition(pos);
        return Math.abs(pos.x - x) < threshold &&
               Math.abs(pos.y - y) < threshold &&
               Math.abs(pos.z - z) < threshold;
    });
}

// Вспомогательная функция для определения цвета грани кубика
function getFaceColor(cube, normal) {
    if (!cube) return null;
    const worldNormal = normal.clone().applyMatrix4(cube.matrixWorld).sub(cube.getWorldPosition(new THREE.Vector3())).normalize();
    const absNormal = new THREE.Vector3(Math.abs(worldNormal.x), Math.abs(worldNormal.y), Math.abs(worldNormal.z));
    let faceColor;
    if (absNormal.x > 0.9) {
        faceColor = worldNormal.x > 0 ? 0xff0000 : 0xffa500; // Красная или оранжевая
    } else if (absNormal.y > 0.9) {
        faceColor = worldNormal.y > 0 ? 0xffffff : 0xffff00; // Белая или жёлтая
    } else if (absNormal.z > 0.9) {
        faceColor = worldNormal.z > 0 ? 0x00ff00 : 0x0000ff; // Зелёная или синяя
    }
    return faceColor;
}

// Функция для получения состояния кубика
function getCubeState() {
    const state = {
        centers: {},
        edges: {},
        corners: {}
    };

    // Определяем центры граней
    const centerCubes = _objects.filter(cube => cube.name.includes("CENTER"));
    centerCubes.forEach(cube => {
        const pos = new THREE.Vector3();
        cube.getWorldPosition(pos);
        const axis = Math.abs(pos.x) > 1.9 ? 'x' : Math.abs(pos.y) > 1.9 ? 'y' : 'z';
        const coord = Math.round(pos[axis]);
        const normal = new THREE.Vector3();
        normal[axis] = coord > 0 ? 1 : -1;
        const color = getFaceColor(cube, normal);
        state.centers[axis + coord] = { cube, color, normal };
    });

    // Определяем рёбра
    const edgeCubes = _objects.filter(cube => !cube.name.includes("CENTER") && cube.name.match(/^[A-Z][0-9]_[A-Z]{2}\d{3}$/));
    edgeCubes.forEach(cube => {
        const pos = new THREE.Vector3();
        cube.getWorldPosition(pos);
        pos.x = Math.round(pos.x * 100) / 100;
        pos.y = Math.round(pos.y * 100) / 100;
        pos.z = Math.round(pos.z * 100) / 100;
        const key = `${pos.x},${pos.y},${pos.z}`;
        const normals = [
            new THREE.Vector3(1, 0, 0), new THREE.Vector3(-1, 0, 0),
            new THREE.Vector3(0, 1, 0), new THREE.Vector3(0, -1, 0),
            new THREE.Vector3(0, 0, 1), new THREE.Vector3(0, 0, -1)
        ];
        const colors = normals.map(normal => getFaceColor(cube, normal)).filter(color => color);
        state.edges[key] = { cube, colors, position: pos };
    });

    // Определяем углы
    const cornerCubes = _objects.filter(cube => !cube.name.includes("CENTER") && cube.name.match(/^[A-Z][0-9]_[A-Z]{3}\d{3}$/));
    cornerCubes.forEach(cube => {
        const pos = new THREE.Vector3();
        cube.getWorldPosition(pos);
        pos.x = Math.round(pos.x * 100) / 100;
        pos.y = Math.round(pos.y * 100) / 100;
        pos.z = Math.round(pos.z * 100) / 100;
        const key = `${pos.x},${pos.y},${pos.z}`;
        const normals = [
            new THREE.Vector3(1, 0, 0), new THREE.Vector3(-1, 0, 0),
            new THREE.Vector3(0, 1, 0), new THREE.Vector3(0, -1, 0),
            new THREE.Vector3(0, 0, 1), new THREE.Vector3(0, 0, -1)
        ];
        const colors = normals.map(normal => getFaceColor(cube, normal)).filter(color => color);
        state.corners[key] = { cube, colors, position: pos };
    });

    return state;
}

// Функция для выполнения стандартных ходов (U, D, L, R, F, B)
async function performMove(face, isCounterclockwise = false) {
    const axes = {
        U: { normal: new THREE.Vector3(0, 1, 0), coord: 2 }, // Верх (белый)
        D: { normal: new THREE.Vector3(0, -1, 0), coord: -2 }, // Низ (жёлтый)
        L: { normal: new THREE.Vector3(-1, 0, 0), coord: -2 }, // Лево (оранжевый)
        R: { normal: new THREE.Vector3(1, 0, 0), coord: 2 }, // Право (красный)
        F: { normal: new THREE.Vector3(0, 0, 1), coord: 2 }, // Фронт (зелёный)
        B: { normal: new THREE.Vector3(0, 0, -1), coord: -2 } // Зад (синий)
    };
    const { normal, coord } = axes[face];
    const cube = findCubeByPosition(
        face === 'L' || face === 'R' ? coord : 0,
        face === 'U' || face === 'D' ? coord : 0,
        face === 'F' || face === 'B' ? coord : 0
    );
    if (cube) {
        console.log(`Выполняется ход ${face}${isCounterclockwise ? "'" : ""}`);
        await rotateLayer(cube, normal, isCounterclockwise);
    } else {
        console.warn(`Кубик для хода ${face} не найден`);
    }
}

