// performs a sequence of moves (in reverse) where each move is of the
// form [function, ...aruments]; note that moves is destroyed!
function performMoves(moves) {
  let nextMove = () => {
    if (moves.length <= 0)
      return;
    const [fn, ...args] = moves.pop();
    fn(...args, nextMove);
  };
  nextMove();
}

