    const currentAngle = rotationGroup.rotation.toVector3().dot(rotationAxis);
    const targetAngle = Math.round(currentAngle / (Math.PI / 2)) * (Math.PI / 2);

    // Анимация завершения
    const duration = 300;
    const startTime = performance.now();

    function animateCompletion(currentTime) {
        if (!rotationGroup) return; // Защита от конфликтов
        const elapsed = currentTime - startTime;
        const progress = Math.min(elapsed / duration, 1);
        const currentAngle = currentAngle + (targetAngle - currentAngle) * progress;

        rotationGroup.rotation.set(0, 0, 0);
        rotationGroup.rotateOnAxis(rotationAxis, currentAngle);

        if (progress < 1) {
            requestAnimationFrame(animateCompletion);
        } else {
            finishRotation();
        }
    }

    requestAnimationFrame(animateCompletion);
