     - **Цвет**: Цвет меняется (например, от красного к зелёному) в зависимости от прогресса.

3. **Привязка к группе вращения**:
   - Стрелки добавляются к `rotationGroup`, чтобы они вращались вместе со слоем и показывали направление относительно оси вращения.

### Реализация
Добавим визуальные стрелки в ваш код. Основные изменения коснутся функции `handleGlobalMouseMove` и `rotateLayer`. Также нужно будет обновить `finishRotation`, чтобы удалять стрелки после завершения вращения.

```javascript
// Глобальная переменная для хранения стрелок прогресса
let progressArrows = [];

function handleGlobalMouseMove(event) {
    if (!isRotating || !rotationGroup) return;

    const currentMousePosition = new THREE.Vector2(event.clientX, event.clientY);
    const delta = currentMousePosition.clone().sub(startMousePosition);

    // Порог для игнорирования мелких движений
    const movementThreshold = 5;
    if (delta.length() < movementThreshold) return;

    // Порог для определения доминирующей оси
    const axisThreshold = 2;
    let dominantAxis = 'none';
    const domX = 'x';
    const domY = 'y';
    if (Math.abs(delta.x) > Math.abs(delta.y) * axisThreshold) {
        dominantAxis = domX; // Горизонтальное
        delta.y = 0;
    } else if (Math.abs(delta.y) > Math.abs(delta.x) * axisThreshold) {
        dominantAxis = domY; // Вертикальное
        delta.x = 0;
    }

    const rotationSpeed = 0.005;
    let rotationAngle = delta.length() * rotationSpeed;

    const mouseDir = delta.clone().normalize();
    const cameraDir = new THREE.Vector3(0, 0, -1).applyQuaternion(camera.quaternion);
    const projAxis = rotationAxis.clone().projectOnPlane(cameraDir).normalize();

    let direction = 0;
    if (Math.abs(rotationAxis.y) > 0.9) {
        if (dominantAxis === domX) {
            direction = mouseDir.x * Math.sign(projAxis.x);
        } else if (dominantAxis === domY) {
            direction = -mouseDir.y * Math.sign(projAxis.y);
        }
    } else if (Math.abs(rotationAxis.x) > 0.9) {
        if (dominantAxis === domY) {
            direction = mouseDir.y * Math.sign(projAxis.y);
        } else if (dominantAxis === domX) {
            direction = mouseDir.x * Math.sign(projAxis.x);
        }
    } else if (Math.abs(rotationAxis.z) > 0.9) {
        if (dominantAxis === domX) {
            direction = mouseDir.x * Math.sign(projAxis.x);
        } else if (dominantAxis === domY) {
            direction = -mouseDir.y * Math.sign(projAxis.y);
        }
    }

    rotationAngle *= Math.sign(direction);

    rotationGroup.rotation.set(0, 0, 0);
    rotationGroup.rotateOnAxis(rotationAxis, rotationAngle);

    // Обновление стрелок прогресса
    updateProgressArrows(rotationAngle);

    startMousePosition.copy(currentMousePosition);
    console.log(`Движение мыши: delta=${delta.x},${delta.y}, dominantAxis=${dominantAxis}, angle=${rotationAngle}`);
}

// Функция для создания и обновления стрелок прогресса
function updateProgressArrows(currentAngle) {
    // Удаляем старые стрелки
    progressArrows.forEach(arrow => scene.remove(arrow));
    progressArrows = [];

    // Вычисляем прогресс (0–1) до ближайшего угла 90°
    const targetAngle = Math.round(currentAngle / (Math.PI / 2)) * (Math.PI / 2);
    const progress = Math.min(Math.abs(currentAngle) / (Math.PI / 2), 1);

    // Создаём две стрелки (в положительном и отрицательном направлении оси)
    const arrowLength = 1 + progress * 2; // Длина от 1 до 3
    const arrowColor = new THREE.Color().lerpColors(
        new THREE.Color(0xff0000), // Красный (0% прогресс)
        new THREE.Color(0x00ff00), // Зелёный (100% прогресс)
        progress
    );

    // Положительная стрелка
    const arrow1 = new THREE.ArrowHelper(
        rotationAxis,
        rotationGroup.position,
        arrowLength,
        arrowColor.getHex(),
        0.3, // Размер наконечника
        0.1  // Размер основания наконечника
    );
    scene.add(arrow1);
    progressArrows.push(arrow1);

    // Отрицательная стрелка
    const arrow2 = new THREE.ArrowHelper(
        rotationAxis.clone().negate(),
        rotationGroup.position,
        arrowLength,
        arrowColor.getHex(),
        0.3,
        0.1
    );
    scene.add(arrow2);
    progressArrows.push(arrow2);
}

function rotateLayer(object, normal) {
    if (isRotating || !object.parent) return;
    console.log('Вращение🔃: ', {
        object: object.name,
        normal: { x: normal.x, y: normal.y, z: normal.z },
        camMode: CurrentActiveCam,
        CubesInLayer: cubesToRotate.length
    });

    const layerData = getCubesInLayer(normal, object);
    cubesToRotate = layerData.cubes;

    if (cubesToRotate.length === 0) return;

    // Удаляем предыдущий arrowHelper
    if (arrowHelper) {
        scene.remove(arrowHelper);
        arrowHelper = null;
    }

    // Удаляем предыдущие стрелки прогресса
    progressArrows.forEach(arrow => scene.remove(arrow));
    progressArrows = [];

    // Создаём группу для вращения
    rotationGroup = new THREE.Group();
    const centerPoint = new THREE.Vector3();

    cubesToRotate.forEach(cube => {
        const pos = new THREE.Vector3();
        cube.getWorldPosition(pos);
        centerPoint.add(pos);
    });
    centerPoint.divideScalar(cubesToRotate.length);

    rotationGroup.position.copy(centerPoint);
    scene.add(rotationGroup);

    cubesToRotate.forEach(cube => {
        const pos = new THREE.Vector3();
        cube.getWorldPosition(pos);
        cube.position.copy(pos.sub(centerPoint));
        scene.remove(cube);
        rotationGroup.add(cube);
    });

    rotationAxis.copy(normal).normalize();
    isRotating = true;

    // Создаём начальные стрелки прогресса
    updateProgressArrows(0);

    // Создаём arrowHelper для оси
    arrowHelper = new THREE.ArrowHelper(
        rotationAxis,
        rotationGroup.position,
        2,
        0xff0000
    );
    scene.add(arrowHelper);
}

function finishRotation() {
    if (!rotationGroup) return;

    cubesToRotate.forEach(cube => {
        cube.traverse(child => {
            if (child.isMesh && originalMaterials.has(child.uuid)) {
                child.material = originalMaterials.get(child.uuid).clone();
                child.material.needsUpdate = true;
                child.geometry.computeVertexNormals();
                if (child.material.emissive) {
                    child.material.emissiveIntensity = 0.5;
                }
            }
        });
    });

    const tempContainer = new THREE.Group();
    scene.add(tempContainer);
    tempContainer.position.copy(rotationGroup.position);
    tempContainer.quaternion.copy(rotationGroup.quaternion);

    while (rotationGroup.children.length > 0) {
        const cube = rotationGroup.children[0];
        const originalPos = new THREE.Vector3().copy(cube.position);
        rotationGroup.remove(cube);
        tempContainer.add(cube);
        cube.position.copy(originalPos);
    }

    while (tempContainer.children.length > 0) {
        const cube = tempContainer.children[0];
        const worldPos = new THREE.Vector3();
        cube.getWorldPosition(worldPos);
        const worldQuater = cube.getWorldQuaternion(new THREE.Quaternion());

        worldPos.x = Math.round(worldPos.x * 1000) / 1000;
        worldPos.y = Math.round(worldPos.y * 1000) / 1000;
        worldPos.z = Math.round(worldPos.z * 1000) / 1000;
        worldQuater.x = Math.round(worldQuater.x * 1000) / 1000;
        worldQuater.y = Math.round(worldQuater.y * 1000) / 1000;
        worldQuater.z = Math.round(worldQuater.z * 1000) / 1000;
        worldQuater.w = Math.round(worldQuater.w * 1000) / 1000;

        tempContainer.remove(cube);
        scene.attach(cube);
        cube.position.copy(worldPos);
        cube.quaternion.copy(worldQuater);
    }

    scene.remove(tempContainer);
    if (arrowHelper) {
        scene.remove(arrowHelper);
        arrowHelper = null;
    }
    // Удаляем стрелки прогресса
    progressArrows.forEach(arrow => scene.remove(arrow));
    progressArrows = [];
    scene.remove(rotationGroup);
    isRotating = false;
    cubesToRotate = [];
    rotationGroup = null;
}
```

### Объяснение изменений
1. **Глобальная переменная `progressArrows`**:
   - Массив для хранения стрелок прогресса, чтобы их можно было удалять и обновлять.

2. **Функция `updateProgressArrows`**:
   - Удаляет старые стрелки и создаёт новые на основе текущего угла поворота.
   - **Прогресс**: Вычисляется как `Math.abs(currentAngle) / (Math.PI / 2)` (0–1, где 1 — полный поворот на 90°).
   - **Длина стрелки**: Варьируется от 1 до 3 в зависимости от прогресса.
   - **Цвет стрелки**: Интерполируется от красного (`0xff0000`) к зелёному (`0x00ff00`) с помощью `lerpColors`.
   - Создаётся две стрелки: одна в положительном направлении оси (`rotationAxis`), другая — в отрицательном.

3. **Инициализация в `rotateLayer`**:
   - При создании `rotationGroup` вызывается `updateProgressArrows(0)` для отображения начальных стрелок с нулевым прогрессом.
   - Удаляются старые стрелки прогресса, если они остались.

4. **Очистка в `finishRotation`**:
   - После завершения вращения все стрелки прогресса удаляются из сцены, а массив `progressArrows` очищается.

