function handleGlobalMouseMove(event) {
    if (!isRotating || !rotationGroup) return;

    const currentMousePosition = new THREE.Vector2(event.clientX, event.clientY);
    const delta = currentMousePosition.clone().sub(startMousePosition);

    // Порог для игнорирования мелких движений (в пикселях)
    const movementThreshold = 10;
    if (delta.length() < movementThreshold) return;

    // Определяем доминирующую ось движения мыши (x или y)
    const axisThreshold = 1.5;
    let dominantAxis = 'none';
    if (Math.abs(delta.x) > Math.abs(delta.y) * axisThreshold) {
        dominantAxis = 'x'; // Горизонтальное движение
        delta.y = 0;       // Игнорируем вертикальное
    } else if (Math.abs(delta.y) > Math.abs(delta.x) * axisThreshold) {
        dominantAxis = 'y'; // Вертикальное движение
        delta.x = 0;       // Игнорируем горизонтальное
    } else {
        return; // Игнорируем, если движение нечёткое
    }

    // Вычисляем угол вращения
    const rotationSpeed = 0.005;
    let rotationAngle = delta.length() * rotationSpeed;

    // Определяем направление движения мыши
    const mouseDir = delta.clone().normalize();

    // Получаем вектор направления камеры
    const cameraDir = new THREE.Vector3(0, 0, -1).applyQuaternion(camera.quaternion);
    const cameraUp = new THREE.Vector3(0, 1, 0).applyQuaternion(camera.quaternion);
    const cameraRight = new THREE.Vector3(1, 0, 0).applyQuaternion(camera.quaternion);

    // Определяем направление вращения
    let direction = 0;
    if (Math.abs(rotationAxis.y) > 0.9) {
        // Для слоёв, вращающихся вокруг y (верх/низ)
        if (dominantAxis === 'x') {
            // Горизонтальное движение мыши
            direction = mouseDir.x * Math.sign(rotationAxis.y) * Math.sign(cameraRight.dot(new THREE.Vector3(1, 0, 0)));
        } else if (dominantAxis === 'y') {
            // Вертикальное движение мыши
            direction = -mouseDir.y * Math.sign(rotationAxis.y) * Math.sign(cameraUp.dot(new THREE.Vector3(0, 1, 0)));
        }
    } else if (Math.abs(rotationAxis.x) > 0.9) {
        // Для слоёв, вращающихся вокруг x (боковые)
        if (dominantAxis === 'y') {
            direction = mouseDir.y * Math.sign(rotationAxis.x) * Math.sign(cameraUp.dot(new THREE.Vector3(0, 1, 0)));
        } else if (dominantAxis === 'x') {
            direction = mouseDir.x * Math.sign(rotationAxis.x) * Math.sign(cameraRight.dot(new THREE.Vector3(1, 0, 0)));
        }
    } else if (Math.abs(rotationAxis.z) > 0.9) {
        // Для слоёв, вращающихся вокруг z (перед/зад)
        if (dominantAxis === 'x') {
            direction = mouseDir.x * Math.sign(rotationAxis.z) * Math.sign(cameraRight.dot(new THREE.Vector3(1, 0, 0)));
        } else if (dominantAxis === 'y') {
            direction = -mouseDir.y * Math.sign(rotationAxis.z) * Math.sign(cameraUp.dot(new THREE.Vector3(0, 1, 0)));
        }
    }

    rotationAngle *= Math.sign(direction);
    if (Math.abs(rotationAngle) < 0.001) return; // Игнорируем слишком малые углы

    rotationGroup.rotation.set(0, 0, 0);
    rotationGroup.rotateOnAxis(rotationAxis, rotationAngle);

    // Обновляем стрелки прогресса (если они есть)
    if (typeof updateProgressArrows === 'function') {
