function handleCubeClick(event) {
    // Предполагается, что у вас есть raycaster, mouse, camera и сцена
    mouse.x = (event.clientX / window.innerWidth) * 2 - 1;
    mouse.y = -(event.clientY / window.innerHeight) * 2 + 1;
    raycaster.setFromCamera(mouse, camera);

    const intersects = raycaster.intersectObjects(scene.children, true);
    if (intersects.length === 0) return;

    const intersect = intersects[0];
    const clickedObject = intersect.object;
    const clickedPos = intersect.point;
    const localNormal = intersect.face.normal.clone();
    const worldNormal = localNormal.clone().applyMatrix4(clickedObject.matrixWorld).sub(clickedObject.position).normalize();

    // Округляем нормаль для выравнивания по основным осям
    let alignedNormal = new THREE.Vector3(
        Math.round(worldNormal.x),
        Math.round(worldNormal.y),
        Math.round(worldNormal.z)
    ).normalize();

    // Определяем слой на основе позиции клика
    let layerCoord, axis;
    if (Math.abs(alignedNormal.x) > 0.9) {
        axis = new THREE.Vector3(Math.sign(alignedNormal.x), 0, 0); // Вращение по x
        layerCoord = Math.round(clickedPos.x * 2) / 2; // Для кубика 3x3: -1, -0.5, 0, 0.5, 1
    } else if (Math.abs(alignedNormal.y) > 0.9) {
        axis = new THREE.Vector3(0, Math.sign(alignedNormal.y), 0); // Вращение по y
        layerCoord = Math.round(clickedPos.y * 2) / 2;
    } else if (Math.abs(alignedNormal.z) > 0.9) {
        axis = new THREE.Vector3(0, 0, Math.sign(alignedNormal.z)); // Вращение по z
        layerCoord = Math.round(clickedPos.z * 2) / 2;
    }

    // Формируем группу для вращения
    rotationGroup = new THREE.Group();
    const cubesToRotate = [];
    scene.children.forEach(cube => {
        const cubePos = cube.position;
        if (Math.abs(cubePos.x - layerCoord) < 0.1 && Math.abs(axis.x) > 0.9 ||
            Math.abs(cubePos.y - layerCoord) < 0.1 && Math.abs(axis.y) > 0.9 ||
            Math.abs(cubePos.z - layerCoord) < 0.1 && Math.abs(axis.z) > 0.9) {
            cubesToRotate.push(cube);
        }
    });

    cubesToRotate.forEach(cube => rotationGroup.add(cube));
    scene.add(rotationGroup);
    rotationAxis = axis;
    isRotating = true;
    startMousePosition = new THREE.Vector2(event.clientX, event.clientY);

    // Отладка
