    // Вычисляем угол вращения
    const rotationSpeed = 0.015;
    let rotationAngle = delta.length() * rotationSpeed;

    // Определяем направление движения мыши
    const mouseDir = delta.clone().normalize();

    // Получаем векторы направления камеры
    const cameraDir = new THREE.Vector3(0, 0, -1).applyQuaternion(camera.quaternion);
    const cameraUp = new THREE.Vector3(0, 1, 0).applyQuaternion(camera.quaternion);
    const cameraRight = new THREE.Vector3(1, 0, 0).applyQuaternion(camera.quaternion);

    // Определяем ось вращения на основе нормали и движения мыши
    let rotationAxis = new THREE.Vector3();
    let direction = 0;

    // Нормаль определяет грань (x, y, z)
    const absNormalX = Math.abs(selectedNormal.x);
    const absNormalY = Math.abs(selectedNormal.y);
    const absNormalZ = Math.abs(selectedNormal.z);

    if (absNormalY > 0.9) {
        // Верхний/нижний слой (нормаль по y)
        if (dominantAxis === 'x') {
            // Горизонтальное движение: вращение по y (влево/вправо)
            rotationAxis.set(0, Math.sign(selectedNormal.y), 0);
            direction = mouseDir.x * Math.sign(selectedNormal.y) * Math.sign(cameraRight.dot(new THREE.Vector3(1, 0, 0)));
        } else if (dominantAxis === 'y') {
