        if (dominantAxis === 'x') {
            // Горизонтальное движение: вращение по z
            rotationAxis.set(0, 0, Math.sign(selectedNormal.x));
            direction = -mouseDir.x * Math.sign(selectedNormal.x) * Math.sign(cameraUp.dot(new THREE.Vector3(0, 1, 0)));
        } else if (dominantAxis === 'y') {
            // Вертикальное движение: вращение по y
            rotationAxis.set(0, 1, 0);
