Давайте создадим файл `CubeInteraction.js` и поместим туда функцию для создания этих триггерных зон. Затем мы импортируем эту функцию в `index.js` и добавим зоны на сцену.

Вот пример содержимого для `CubeInteraction.js`, основанный на изображении и обсуждении:

**1. Создайте новый файл: `CubeInteraction.js`**

```javascript
// CubeInteraction.js
import * as THREE from 'three';

/**
 * Создает невидимые триггерные зоны вокруг кубика для определения вращений по свайпу на ребрах.
 * @param {number} cubeSize Размер кубика (например, 3 для 3x3x3).
 * @returns {THREE.Mesh[]} Массив мешей триггерных зон.
 */
export function createTriggerZones(cubeSize = 3) {
    const zones = [];
    const halfSize = cubeSize / 2; // Половина размера кубика
    const zoneSize = 0.6; // Размер зоны вдоль ребра и перпендикулярно внутрь
    const zoneThickness = 0.1; // Толщина зоны (насколько она выступает наружу)
    const outwardOffset = 0.05; // Небольшой отступ от грани/ребра наружу

    // Материал для зон (делаем его невидимым в финальной версии)
    const zoneMaterial = new THREE.MeshBasicMaterial({
        color: 0x00ffff, // Цвет для отладки (бирюзовый)
        wireframe: true, // Показываем каркас для отладки
        transparent: true,
        opacity: 0.1, // Делаем полупрозрачным для отладки
        visible: false // Установите true для отладки, false для продакшена
    });

    // Определяем позиции слоев вдоль осей (для 3x3x3 кубика размером 3)
    const layerPositions = [1, 0, -1]; // Координаты центров слоев

    // Определение ребер и связанных с ними свойств
    // Для каждого ребра:
    // - fixedCoords: координаты, которые остаются постоянными на этом ребре
    // - edgeAxis: ось, вдоль которой идет ребро ('x', 'y', или 'z')
    // - layerPositions: массив координат вдоль edgeAxis для каждого из 3 слоев
    // - outwardDir: вектор, указывающий наружу от центра кубика через это ребро
    // - triggeredFace: грань, вращение которой запускается этим ребром (по свайпу в направлении outwardDir)
    const edges = [
        // Ребра вдоль оси Y (фиксированные X, Z) - запускают вращение R/L (вокруг X)
        // Зоны на этих ребрах соответствуют слоям R/L по их X-координате.
        // Позиция зоны вдоль Y (1, 0, -1) соответствует слою R/L с X-координатой (1, 0, -1).
        { fixedX: halfSize, fixedZ: halfSize, edgeAxis: 'y', layerPositions: [1, 0, -1], outwardDir: new THREE.Vector3(1, 0, 1), triggeredFace: 'right' }, // F-R (стрелки +X -> R)
        { fixedX: halfSize, fixedZ: -halfSize, edgeAxis: 'y', layerPositions: [1, 0, -1], outwardDir: new THREE.Vector3(1, 0, -1), triggeredFace: 'right' }, // B-R (стрелки +X -> R)
        { fixedX: -halfSize, fixedZ: halfSize, edgeAxis: 'y', layerPositions: [1, 0, -1], outwardDir: new THREE.Vector3(-1, 0, 1), triggeredFace: 'left' }, // F-L (стрелки -X -> L)
        { fixedX: -halfSize, fixedZ: -halfSize, edgeAxis: 'y', layerPositions: [1, 0, -1], outwardDir: new THREE.Vector3(-1, 0, -1), triggeredFace: 'left' }, // B-L (стрелки -X -> L)

        // Ребра вдоль оси X (фиксированные Y, Z) - запускают вращение U/D (вокруг Y)
        // Зоны на этих ребрах соответствуют слоям U/D по их Y-координате.
        // Позиция зоны вдоль X (1, 0, -1) соответствует слою U/D с Y-координатой (1, 0, -1).
        { fixedY: halfSize, fixedZ: halfSize, edgeAxis: 'x', layerPositions: [1, 0, -1], outwardDir: new THREE.Vector3(0, 1, 1), triggeredFace: 'up' }, // F-T (стрелки +Y -> U)
        { fixedY: -halfSize, fixedZ: halfSize, edgeAxis: 'x', layerPositions: [1, 0, -1], outwardDir: new THREE.Vector3(0, -1, 1), triggeredFace: 'down' }, // F-Btm (стрелки -Y -> D)
        { fixedY: halfSize, fixedZ: -halfSize, edgeAxis: 'x', layerPositions: [1, 0, -1], outwardDir: new THREE.Vector3(0, 1, -1), triggeredFace: 'up' }, // B-T (стрелки +Y -> U)
        { fixedY: -halfSize, fixedZ: -halfSize, edgeAxis: 'x', layerPositions: [1, 0, -1], outwardDir: new THREE.Vector3(0, -1, -1), triggeredFace: 'down' }, // B-Btm (стрелки -Y -> D)

        // Ребра вдоль оси Z (фиксированные X, Y) - запускают вращение F/B (вокруг Z) - ИЛИ R/L по изображению?
        // По изображению, стрелки на T-R ребре (+X) запускают R/R'.
        // Давайте следовать изображению: Ребра вдоль Z запускают R/L (вокруг X).
        // Зоны на этих ребрах соответствуют слоям R/L по их X-координате.
        // Позиция зоны вдоль Z (1, 0, -1) соответствует слою R/L с X-координатой (1, 0, -1).
        { fixedX: halfSize, fixedY: halfSize, edgeAxis: 'z', layerPositions: [1, 0, -1], outwardDir: new THREE.Vector3(1, 1, 0), triggeredFace: 'right' }, // T-R (стрелки +X -> R)
        { fixedX: -halfSize, fixedY: halfSize, edgeAxis: 'z', layerPositions: [1, 0, -1], outwardDir: new THREE.Vector3(-1, 1, 0), triggeredFace: 'left' }, // T-L (стрелки -X -> L)
        { fixedX: halfSize, fixedY: -halfSize, edgeAxis: 'z', layerPositions: [1, 0, -1], outwardDir: new THREE.Vector3(1, -1, 0), triggeredFace: 'right' }, // Btm-R (стрелки +X -> R)
        { fixedX: -halfSize, fixedY: -halfSize, edgeAxis: 'z', layerPositions: [1, 0, -1], outwardDir: new THREE.Vector3(-1, -1, 0), triggeredFace: 'left' }, // Btm-L (стрелки -X -> L)
    ];

    // Геометрия зоны (ширина, высота, глубина).
    // Мы будем вращать эту геометрию так, чтобы ее локальная Z-ось указывала наружу.
    // Локальная Y-ось будет вдоль ребра. Локальная X-ось перпендикулярно внутрь.
    const zoneGeometry = new THREE.BoxGeometry(zoneSize, zoneSize, zoneThickness); // width, height, depth

    edges.forEach(edge => {
        const outwardVector = edge.outwardDir.clone().normalize(); // Нормализованный вектор наружу

        edge.layerPositions.forEach((layerPos, index) => {
            const zone = new THREE.Mesh(zoneGeometry, zoneMaterial);

            // Вычисляем позицию зоны
            const position = new THREE.Vector3();
            if (edge.edgeAxis === 'y') {
                position.set(edge.fixedX, layerPos, edge.fixedZ);
            } else if (edge.edgeAxis === 'x') {
                position.set(layerPos, edge.fixedY, edge.fixedZ);
            } else if (edge.edgeAxis === 'z') {
                position.set(edge.fixedX, edge.fixedY, layerPos);
            }

            // Добавляем смещение наружу
            position.add(outwardVector.clone().multiplyScalar(zoneThickness / 2 + outwardOffset));

            zone.position.copy(position);

            // Вычисляем вращение зоны так, чтобы ее локальная Z-ось указывала в направлении outwardVector
            const quaternion = new THREE.Quaternion();
            // BoxGeometry по умолчанию ориентирована так, что Z+ направлен "вперед".
            // Мы хотим повернуть ее так, чтобы Z+ был направлен в сторону outwardVector.
            quaternion.setFromUnitVectors(new THREE.Vector3(0, 0, 1), outwardVector);
            zone.quaternion.copy(quaternion);

            // Добавляем пользовательские данные для идентификации зоны
            zone.userData = {
                isTriggerZone: true,
                triggeredFace: edge.triggeredFace, // 'right', 'left', 'up', 'down', 'front', 'back'
                layerIndex: index, // 0, 1, 2 (от +координаты к -координате вдоль оси вращения)
                // layerCoord: layerPos // Можно сохранить координату слоя, если нужно
            };

            zones.push(zone);
        });
    });

    return zones;
}
```

**Объяснение кода `CubeInteraction.js`:**

1.  **Импорт Three.js:** Импортируем библиотеку.
2.  **`createTriggerZones` функция:** Принимает `cubeSize` и возвращает массив мешей зон.
3.  **Константы:** Определяем размеры кубика, зон и смещения.
4.  **`zoneMaterial`:** Создаем базовый материал. Важно установить `visible: false` для конечного приложения, но `wireframe: true` и `opacity` полезны для отладки размещения зон.
5.  **`layerPositions`:** Массив `[1, 0, -1]` представляет координаты центров слоев для кубика размером 3, центрированного в начале координат.
6.  **`edges` массив:** Это ключевая структура данных. Каждый объект в массиве описывает одно из 12 ребер кубика:
    *   `fixedX`, `fixedY`, `fixedZ`: Координаты, которые являются постоянными для точек на этом ребре.
    *   `edgeAxis`: Ось, вдоль которой вытянуто ребро ('x', 'y', или 'z').
    *   `layerPositions`: Координаты `[1, 0, -1]` вдоль `edgeAxis`, где будут размещены 3 зоны.
    *   `outwardDir`: Вектор, указывающий из центра кубика наружу через это ребро. Используется для позиционирования и ориентации зоны.
    *   `triggeredFace`: Строка, указывающая, вращение какой грани запускает эта группа зон ('right', 'left', 'up', 'down', 'front', 'back'). Это основано на интерпретации стрелок на изображении.
7.  **`zoneGeometry`:** Создаем геометрию коробки для зоны.
8.  **Циклы по ребрам и слоям:** Перебираем каждое ребро, а затем для каждого ребра перебираем 3 позиции слоев вдоль этого ребра.
9.  **Создание меша зоны:** Создаем `THREE.Mesh` для каждой зоны.
10. **Вычисление позиции:** Определяем базовую позицию зоны на ребре, используя `fixedCoords` и `layerPos` для текущего слоя. Затем добавляем небольшое смещение наружу в направлении `outwardVector`.
11. **Вычисление вращения:** Создаем кватернион, который поворачивает стандартную ориентацию `BoxGeometry` (где Z+ "смотрит" вперед) так, чтобы локальная Z-ось зоны указывала в направлении `outwardVector`.
12. **Пользовательские данные (`userData`):** Добавляем к мешу объект `userData`. Это очень важно!
    *   `isTriggerZone: true`: Флаг, чтобы легко определить, является ли объект зоной при Raycasting'е.
    *   `triggeredFace`: Имя грани, вращение которой запускает эта зона.
    *   `layerIndex`: Индекс слоя (0, 1, или 2), соответствующий позиции зоны вдоль ребра. Это позволит вам определить, какой именно слой вращать.
13. **Добавление в массив:** Добавляем созданную зону в массив `zones`.
14. **Возврат массива:** Функция возвращает массив всех созданных зон.

**2. Модифицируйте `index.js`**

Теперь вам нужно импортировать эту функцию в `index.js`, вызвать ее и добавить полученные зоны на сцену. Вам также потребуется включить эти зоны в список объектов, которые проверяет ваш `Raycaster` при движении мыши.

```javascript
// index.js
import * as THREE from 'three';
import { createCube } from './cube.js';
import { createPlayer } from './player.js';
import { createTriggerZones } from './CubeInteraction.js'; // <--- Импортируем функцию

// ... (ваш существующий код настройки сцены, камеры, рендерера) ...

// Предполагаем, что у вас есть глобальные переменные или переменные в области видимости
let scene;
let camera;
let renderer;
let cube; // Группа, содержащая все маленькие кубики
let raycaster;
let mouse; // THREE.Vector2 для позиции мыши

// Переменные состояния для взаимодействия
let isDragging = false;
let selectedFace = null; // Грань кликнутого стикера ('front', 'up', etc.)
let selectedLayer = null; // Слой кликнутого стикера (0, 1, 2)
let initialMousePosition = new THREE.Vector2(); // Начальная 2D позиция мыши при клике
let currentMousePosition = new THREE.Vector2(); // Текущая 2D позиция мыши

let rotationTriggerZones = []; // <--- Массив для хранения триггерных зон
let interactiveObjects = []; // Массив объектов для Raycaster'а (стикеры + зоны)

// ... (ваш существующий код инициализации: scene, camera, renderer, raycaster, mouse) ...

function init() {
    // ... (ваш существующий код инициализации) ...

    // Создаем кубик
    cube = createCube(); // Убедитесь, что createCube возвращает THREE.Group
    scene.add(cube);

    // Создаем триггерные зоны
    rotationTriggerZones = createTriggerZones(3); // Создаем зоны для кубика размером 3
    rotationTriggerZones.forEach(zone => scene.add(zone)); // Добавляем зоны в сцену

    // Объединяем стикеры кубика и триггерные зоны для Raycasting'а
    // Предполагаем, что cube.children - это маленькие кубики или их стикеры,
    // которые вы хотите кликать для начала взаимодействия.
    // Если кликабельные объекты - это стикеры, убедитесь, что они доступны.
    // Если кликабельные объекты - это маленькие кубики, используйте cube.children.
    // Давайте предположим, что вы кликаете по маленьким кубикам (или их оболочкам),
    // и у них есть userData с информацией о грани и слое.
    // Если у вас кликабельные стикеры, замените cube.children на массив стикеров.
    interactiveObjects = [...cube.children, ...rotationTriggerZones]; // Raycaster будет проверять и кубики/стикеры, и зоны

    // ... (ваш существующий код добавления света, земли и т.д.) ...

    // Добавляем обработчики событий
    window.addEventListener('mousedown', onMouseDown, false);
    window.addEventListener('mousemove', onMouseMove, false); // Используем один обработчик для всего движения
    window.addEventListener('mouseup', onMouseUp, false);

    // ... (остальная часть init) ...
}


function onMouseDown(event) {
    // Обновляем позицию мыши
    mouse.x = (event.clientX / window.innerWidth) * 2 - 1;
    mouse.y = -(event.clientY / window.innerHeight) * 2 + 1;

    // Создаем Raycaster
    raycaster.setFromCamera(mouse, camera);

    // Проверяем пересечения с интерактивными объектами (кубики/стикеры + зоны)
    const intersects = raycaster.intersectObjects(interactiveObjects);

    if (intersects.length > 0) {
        const intersectedObject = intersects[0].object;

        // Проверяем, кликнули ли по стикеру/кубику, чтобы начать перетаскивание
        // Вам нужно убедиться, что у ваших кликабельных объектов есть userData
        // с информацией о грани и слое.
        // Пример: intersectedObject.userData = { isSticker: true, face: 'front', layer: 1 }
        if (intersectedObject.userData && intersectedObject.userData.isSticker) { // <--- Условие зависит от вашей структуры cube.js
             // Если кликнули по стикеру/кубику, начинаем "тащить"
             isDragging = true;
             selectedFace = intersectedObject.userData.face; // Грань, по которой кликнули
             selectedLayer = intersectedObject.userData.layer; // Слой, по которому кликнули
             initialMousePosition.x = mouse.x; // Сохраняем начальную 2D позицию мыши
             initialMousePosition.y = mouse.y;

             console.log(`Начато перетаскивание. Клик по грани: ${selectedFace}, слой: ${selectedLayer}`);

             // Здесь пока не определяем rotationGroup, это произойдет при движении в зону
        }
         // Если кликнули прямо по зоне (менее вероятно, но возможно), игнорируем начало перетаскивания
         // или обрабатываем как мгновенное вращение, если это нужно.
         // В данной логике зоны используются только для определения ВРАЩЕНИЯ ПОСЛЕ клика по стикеру.
    }
}

function onMouseMove(event) {
     // Обновляем текущую позицию мыши
     currentMousePosition.x = (event.clientX / window.innerWidth) * 2 - 1;
     currentMousePosition.y = -(event.clientY / window.innerHeight) * 2 + 1;

    if (!isDragging || isAnimating) return; // Двигаем только если "тащим" и нет анимации

    // Создаем Raycaster из текущей позиции мыши
    raycaster.setFromCamera(currentMousePosition, camera);

    // Проверяем пересечение ТОЛЬКО с триггерными зонами
    const intersects = raycaster.intersectObjects(rotationTriggerZones);

    if (intersects.length > 0) {
        const intersectedZone = intersects[0].object;

        if (intersectedZone.userData && intersectedZone.userData.isTriggerZone) {
            const { triggeredFace, layerIndex } = intersectedZone.userData;

            console.log(`Пересечена зона: ${triggeredFace}, слой: ${layerIndex}`);

            // --- Логика определения направления свайпа и запуска вращения ---
            // Здесь вам нужно определить, в каком направлении двигалась мышь
            // ОТ начальной позиции клика ДО момента пересечения этой зоны.
            // Сравните initialMousePosition и currentMousePosition.
            // Направление свайпа на 2D экране нужно сопоставить с 3D вращением для triggeredFace.

            // Пример (упрощенно): Определяем направление по 2D движению мыши
            const swipeDelta = new THREE.Vector2().subVectors(currentMousePosition, initialMousePosition);
            const swipeThreshold = 0.05; // Порог для определения свайпа

            let rotationDirection = 0; // 1 для по часовой, -1 для против часовой

            // Логика определения направления зависит от triggeredFace и ориентации кубика/камеры
            // Это самая сложная часть. Вам нужно понять, какое 2D движение мыши
            // соответствует повороту по часовой/против часовой для данной грани.

            // Например, для triggeredFace 'right' (вращение вокруг X):
            // При стандартной ориентации камеры, свайп ВВЕРХ на экране -> R' (против часовой)
            // При стандартной ориентации камеры, свайп ВНИЗ на экране -> R (по часовой)
            if (triggeredFace === 'right' || triggeredFace === 'left') {
                 if (Math.abs(swipeDelta.y) > Math.abs(swipeDelta.x) && Math.abs(swipeDelta.y) > swipeThreshold) {
                     // Вертикальный свайп для R/L
                     if (triggeredFace === 'right') {
                         rotationDirection = swipeDelta.y < 0 ? 1 : -1; // Вниз -> R, Вверх -> R'
                     } else { // left
                         rotationDirection = swipeDelta.y < 0 ? -1 : 1; // Вниз -> L', Вверх -> L
                     }
                 }
            }
            // Для triggeredFace 'up'/'down' (вращение вокруг Y):
            // При стандартной ориентации камеры, свайп ВПРАВО на экране -> U (по часовой)
            // При стандартной ориентации камеры, свайп ВЛЕВО на экране -> U' (против часовой)
             if (triggeredFace === 'up' || triggeredFace === 'down') {
                 if (Math.abs(swipeDelta.x) > Math.abs(swipeDelta.y) && Math.abs(swipeDelta.x) > swipeThreshold) {
                     // Горизонтальный свайп для U/D
                     if (triggeredFace === 'up') {
                         rotationDirection = swipeDelta.x > 0 ? 1 : -1; // Вправо -> U, Влево -> U'
                     } else { // down
                         rotationDirection = swipeDelta.x > 0 ? -1 : 1; // Вправо -> D', Влево -> D
                     }
