### Примерный план изменений:

#### 1. **`CubeInteraction.js`**
Создаем триггерные зоны для каждого угла кубика (всего 8 углов). Каждая зона — это небольшой объем (например, куб размером `smallCubeSize * 0.5`), расположенный в углу кубика. Каждая зона связана с гранью и направлением вращения.

```javascript
// CubeInteraction.js
import * as THREE from 'three';

export function createTriggerZones(cubeSize = 6.12) {
    const zones = [];
    const halfSize = cubeSize / 2; // 3.06
    const smallCubeSize = cubeSize / 3; // 2.04
    const zoneSize = smallCubeSize * 0.5; // Размер угловой зоны, например, 1.02
    const zoneOffset = halfSize - zoneSize / 2; // Смещение зоны к углу, чтобы центр зоны был в углу

    // Материал для зон (невидимый в продакшене)
    const zoneMaterial = new THREE.MeshBasicMaterial({
        color: 0x00ffff,
        wireframe: true,
        transparent: true,
        opacity: 0.1,
        visible: false // true для отладки
    });

    // Определяем углы кубика и связанные направления вращения
    const corners = [
        // Угол (+X, +Y, +Z)
        { position: new THREE.Vector3(zoneOffset, zoneOffset, zoneOffset), face: 'right', rotationDir: 'clockwise' },
        { position: new THREE.Vector3(zoneOffset, zoneOffset, zoneOffset), face: 'up', rotationDir: 'clockwise' },
        { position: new THREE.Vector3(zoneOffset, zoneOffset, zoneOffset), face: 'front', rotationDir: 'clockwise' },
        // Угол (+X, +Y, -Z)
        { position: new THREE.Vector3(zoneOffset, zoneOffset, -zoneOffset), face: 'right', rotationDir: 'clockwise' },
        { position: new THREE.Vector3(zoneOffset, zoneOffset, -zoneOffset), face: 'up', rotationDir: 'clockwise' },
        { position: new THREE.Vector3(zoneOffset, zoneOffset, -zoneOffset), face: 'back', rotationDir: 'clockwise' },
        // Угол (+X, -Y, +Z)
        { position: new THREE.Vector3(zoneOffset, -zoneOffset, zoneOffset), face: 'right', rotationDir: 'clockwise' },
        { position: new THREE.Vector3(zoneOffset, -zoneOffset, zoneOffset), face: 'down', rotationDir: 'clockwise' },
        { position: new THREE.Vector3(zoneOffset, -zoneOffset, zoneOffset), face: 'front', rotationDir: 'clockwise' },
        // Угол (+X, -Y, -Z)
        { position: new THREE.Vector3(zoneOffset, -zoneOffset, -zoneOffset), face: 'right', rotationDir: 'clockwise' },
        { position: new THREE.Vector3(zoneOffset, -zoneOffset, -zoneOffset), face: 'down', rotationDir: 'clockwise' },
        { position: new THREE.Vector3(zoneOffset, -zoneOffset, -zoneOffset), face: 'back', rotationDir: 'clockwise' },
        // Угол (-X, +Y, +Z)
        { position: new THREE.Vector3(-zoneOffset, zoneOffset, zoneOffset), face: 'left', rotationDir: 'clockwise' },
        { position: new THREE.Vector3(-zoneOffset, zoneOffset, zoneOffset), face: 'up', rotationDir: 'clockwise' },
        { position: new THREE.Vector3(-zoneOffset, zoneOffset, zoneOffset), face: 'front', rotationDir: 'clockwise' },
        // Угол (-X, +Y, -Z)
        { position: new THREE.Vector3(-zoneOffset, zoneOffset, -zoneOffset), face: 'left', rotationDir: 'clockwise' },
        { position: new THREE.Vector3(-zoneOffset, zoneOffset, -zoneOffset), face: 'up', rotationDir: 'clockwise' },
        { position: new THREE.Vector3(-zoneOffset, zoneOffset, -zoneOffset), face: 'back', rotationDir: 'clockwise' },
        // Угол (-X, -Y, +Z)
        { position: new THREE.Vector3(-zoneOffset, -zoneOffset, zoneOffset), face: 'left', rotationDir: 'clockwise' },
        { position: new THREE.Vector3(-zoneOffset, -zoneOffset, zoneOffset), face: 'down', rotationDir: 'clockwise' },
        { position: new THREE.Vector3(-zoneOffset, -zoneOffset, zoneOffset), face: 'front', rotationDir: 'clockwise' },
        // Угол (-X, -Y, -Z)
        { position: new THREE.Vector3(-zoneOffset, -zoneOffset, -zoneOffset), face: 'left', rotationDir: 'clockwise' },
        { position: new THREE.Vector3(-zoneOffset, -zoneOffset, -zoneOffset), face: 'down', rotationDir: 'clockwise' },
        { position: new THREE.Vector3(-zoneOffset, -zoneOffset, -zoneOffset), face: 'back', rotationDir: 'clockwise' },
    ];

    // Геометрия зоны (кубик)
    const zoneGeometry = new THREE.BoxGeometry(zoneSize, zoneSize, zoneSize);

    corners.forEach((corner, index) => {
        const zone = new THREE.Mesh(zoneGeometry, zoneMaterial);
        zone.position.copy(corner.position);

        // Сохраняем данные для обработки
        zone.userData = {
            isTriggerZone: true,
            triggeredFace: corner.face, // 'right', 'left', 'up', 'down', 'front', 'back'
            rotationDir: corner.rotationDir, // 'clockwise' или 'counterclockwise'
        };

        zones.push(zone);
    });

    return zones;
}
```

#### 2. **`index.js`**
Обновляем обработку мыши, чтобы фиксировать грань при нажатии и определять угловую зону при перетаскивании.

```javascript
// index.js
import * as THREE from 'three';
import { createCube } from './cube.js';
import { createTriggerZones } from './CubeInteraction.js';

let scene, camera, renderer, cube, rotationTriggerZones;
let selectedFace = null;
let startPoint = null;

function init() {
    scene = new THREE.Scene();
    camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
    camera.position.z = 10;
    renderer = new THREE.WebGLRenderer();
    renderer.setSize(window.innerWidth, window.innerHeight);
    document.body.appendChild(renderer.domElement);

    cube = createCube();
    scene.add(cube);

    const actualCubeSize = 6.12;
    rotationTriggerZones = createTriggerZones(actualCubeSize);
    rotationTriggerZones.forEach(zone => scene.add(zone));

    const raycaster = new THREE.Raycaster();
    const mouse = new THREE.Vector2();

    function onMouseDown(event) {
        mouse.x = (event.clientX / window.innerWidth) * 2 - 1;
        mouse.y = -(event.clientY / window.innerHeight) * 2 + 1;
        raycaster.setFromCamera(mouse, camera);

        const intersects = raycaster.intersectObjects(cube.children, true);
        if (intersects.length > 0) {
            const intersected = intersects[0].object;
            if (intersected.userData.isCubelet) {
                selectedFace = intersected.userData.face; // Предполагается, что у кублетов есть userData.face
                startPoint = intersects[0].point.clone();
            }
        }
    }

    function onMouseMove(event) {
        if (selectedFace && startPoint) {
            mouse.x = (event.clientX / window.innerWidth) * 2 - 1;
            mouse.y = -(event.clientY / window.innerHeight) * 2 + 1;
            raycaster.setFromCamera(mouse, camera);

            const intersects = raycaster.intersectObjects(rotationTriggerZones);
            if (intersects.length > 0) {
                const zone = intersects[0].object;
                const triggeredFace = zone.userData.triggeredFace;
                const rotationDir = zone.userData.rotationDir;

                if (triggeredFace === selectedFace) {
                    // Запускаем вращение грани
                    rotateFace(triggeredFace, rotationDir);
                }
            }
        }
    }

    function onMouseUp() {
        selectedFace = null;
        startPoint = null;
    }

    function rotateFace(face, direction) {
        // Функция для вращения грани (нужно реализовать в cube.js)
        // Например, вызвать getRotationGroup и повернуть группу
        console.log(`Вращаем грань ${face} ${direction}`);
    }

    document.addEventListener('mousedown', onMouseDown);
    document.addEventListener('mousemove', onMouseMove);
    document.addEventListener('mouseup', onMouseUp);

    animate();
}

function animate() {
    requestAnimationFrame(animate);
    renderer.render(scene, camera);
}

init();
