// cube.js
import * as THREE from 'three';

export function createCube() {
    const cube = new THREE.Group();
    const cubeSize = 6.12;
    const smallCubeSize = cubeSize / 3; // 2.04
    const geometry = new THREE.BoxGeometry(smallCubeSize * 0.95, smallCubeSize * 0.95, smallCubeSize * 0.95);
    const material = new THREE.MeshBasicMaterial({ color: 0xffffff });

    // Создаем 3x3x3 кубики
    for (let x = -1; x <= 1; x++) {
        for (let y = -1; y <= 1; y++) {
            for (let z = -1; z <= 1; z++) {
                const cubelet = new THREE.Mesh(geometry, material);
                cubelet.position.set(x * smallCubeSize, y * smallCubeSize, z * smallCubeSize);
                cubelet.userData = {
                    isCubelet: true,
                    face: determineFace(x, y, z), // Функция для определения грани
                };
                cube.add(cubelet);
            }
        }
    }

    return cube;
}

function determineFace(x, y, z) {
    // Определяем, к какой грани относится кублет
    if (x === 1) return 'right';
    if (x === -1) return 'left';
    if (y === 1) return 'up';
    if (y === -1) return 'down';
    if (z === 1) return 'front';
    if (z === -1) return 'back';
