function getAxisFromFace(face) {
    const axes = {
        'right': new THREE.Vector3(1, 0, 0),
        'left': new THREE.Vector3(-1, 0, 0),
        'up': new THREE.Vector3(0, 1, 0),
        'down': new THREE.Vector3(0, -1, 0),
        'front': new THREE.Vector3(0, 0, 1),
        'back': new THREE.Vector3(0, 0, -1)
    };
    return axes[face];
