// Оптимизированная функция вращения слоя
function rotateLayer(object, axis, layerIndex) {
    if (rotationInProgress) return;

    rotationInProgress = true;
    const cubesInLayer = getCubesInLayer(object, axis, layerIndex); // Предполагается, что функция оптимизирована
    const angle = Math.PI / 2; // 90 градусов

    // Анимация вращения
    const rotationGroup = new THREE.Group();
    scene.add(rotationGroup);
    cubesInLayer.forEach(cube => rotationGroup.add(cube));

    const duration = 500; // ms
    let startTime = null;

    function animateRotation(timestamp) {
        if (!startTime) startTime = timestamp;
        const progress = (timestamp - startTime) / duration;

        rotationGroup.setRotationFromAxisAngle(axis, angle * progress);

        if (progress < 1) {
            requestAnimationFrame(animateRotation);
        } else {
            // Финализация вращения
            cubesInLayer.forEach(cube => {
                cube.applyMatrix4(rotationGroup.matrix);
                scene.add(cube);
            });
            scene.remove(rotationGroup);
            rotationInProgress = false;
        }
    }
    requestAnimationFrame(animateRotation);
}

// Оптимизированная функция получения кубиков в слое
function getCubesInLayer(object, axis, layerIndex) {
    // Предполагаем, что кубики уже сгруппированы по слоям в глобальной структуре
    const layerKey = `${axis.x},${axis.y},${axis.z}:${layerIndex}`;
    return layerCache[layerKey] || computeCubesInLayer(object, axis, layerIndex); // Кэшируем слои
}

// Вычисление кубиков в слое (вызывается только при отсутствии в кэше)
function computeCubesInLayer(object, axis, layerIndex) {
    const cubes = objects.filter(cube => {
        const pos = cube.position.clone().applyMatrix4(object.matrixWorld);
        const coord = pos.dot(axis);
        return Math.abs(coord - layerIndex) < 0.1; // Погрешность для чисел с плавающей точкой
    });
    layerCache[layerKey] = cubes; // Сохраняем в кэш
    return cubes;
}

// Глобальный кэш для слоёв
const layerCache = {};
