### Исправленный и структурированный код:

```matlab
x = 0:0.01:20; % Определение диапазона значений по оси X

% Примерные значения для функций принадлежности множеств A, B, C
M_A = rand(1, length(x)); % Замените на реальные значения функции принадлежности для A
M_B = rand(1, length(x)); % Замените на реальные значения функции принадлежности для B
M_C = rand(1, length(x)); % Замените на реальные значения функции принадлежности для C

% Инициализация массивов для расчетов
M_n_A = zeros(1, length(x));      % Дополнение A
M_A_B = zeros(1, length(x));      % Объединение A и B
M_A_B_C = zeros(1, length(x));    % Объединение A, B и C
M_D = zeros(1, length(x));        % Результат - множество D

% Последовательные расчеты для построения множества D
for j = 1:length(x)
    % Шаг 1: Дополнение A
    M_n_A(j) = 1 - M_A(j); % Дополнение множества A

    % Шаг 2: Объединение A и B
    if (M_A(j) + M_B(j)) < 1
        M_A_B(j) = M_A(j) + M_B(j); % Суммирование степеней принадлежности
    else
        M_A_B(j) = 1; % Максимальная степень принадлежности не может превышать 1
    end

    % Шаг 3: Объединение (A ∪ B) и C
    if (M_A_B(j) + M_C(j)) < 1
        M_A_B_C(j) = M_A_B(j) + M_C(j); % Объединение A, B и C
    else
        M_A_B_C(j) = 1;
    end

    % Шаг 4: Пересечение дополнения A с объединением A ∪ C ∪ B
    if (M_A_B_C(j) + M_n_A(j) - 1) > 0
        M_D(j) = M_A_B_C(j) + M_n_A(j) - 1; % Применяем правило пересечения
    else
        M_D(j) = 0;
    end
end

% Построение графиков для визуализации
subplot(2, 3, 1);
plot(x, M_A, 'LineWidth', 2); grid on; xlabel('X'); ylabel('M_A(\mu)');
title('Множество A');

