plot(x, M_B, 'LineWidth', 2); grid on; xlabel('X'); ylabel('M_B(\mu)');
title('Множество B');

subplot(2, 3, 3);
plot(x, M_C, 'LineWidth', 2); grid on; xlabel('X'); ylabel('M_C(\mu)');
title('Множество C');

subplot(2, 3, 4);
