title('Дополнение A');

subplot(2, 3, 5);
plot(x, M_A_B_C, 'LineWidth', 2); grid on; xlabel('X'); ylabel('M_A_B_C(\mu)');
title('Объединение A ∪ B ∪ C');

subplot(2, 3, 6);
plot(x, M_D, 'LineWidth', 2, 'Color', 'm'); grid on; xlabel('X'); ylabel('M_D(\mu)');
title('Множество D = дополнение(A) ∩ (A ∪ B ∪ C)');
