```csharp
using System;
using System.Windows.Forms;
using System.Drawing;
using System.Collections.Generic;
using System.IO;
using iTextSharp.text;
using iTextSharp.text.pdf;

namespace ArtUploaderApp
{
    public partial class MainForm : Form
    {
        private List<ArtWork> artWorks = new List<ArtWork>();
        private bool isLicensed = false;

        public MainForm()
        {
            InitializeComponent();
            CheckLicense();
        }

        private void CheckLicense()
        {
            // Проверка лицензии (упрощенный пример)
            string licenseKey = GetLicenseKey();
            if (ValidateLicense(licenseKey))
            {
                isLicensed = true;
                MessageBox.Show("Лицензия подтверждена");
            }
            else
            {
                MessageBox.Show("Необходимо ввести лицензионный ключ для полной версии");
                isLicensed = false;
            }
        }

        private bool ValidateLicense(string key)
        {
            // Заглушка проверки лицензии
            return key == "YOUR_LICENSE_KEY";
        }

        private string GetLicenseKey()
        {
            // Получение ключа лицензии из файла/реестра или UI
            return "YOUR_LICENSE_KEY";
        }

        private void btnAddArtWork_Click(object sender, EventArgs e)
        {
            // Добавление новой работы через форму
            var newArtWork = new ArtWorkForm().GetArtWork();
            if (newArtWork != null)
            {
                artWorks.Add(newArtWork);
                UpdateArtWorkList();
            }
        }

        private void UpdateArtWorkList()
        {
            listBoxArtWorks.Items.Clear();
            foreach (var work in artWorks)
            {
                listBoxArtWorks.Items.Add(work.Title);
            }
        }

        private void btnPublish_Click(object sender, EventArgs e)
        {
            if (!isLicensed)
            {
                MessageBox.Show("Публикация доступна только в полной версии.");
                return;
            }

            foreach (var site in SupportedSites())
            {
                foreach (var work in artWorks)
                {
                    // Публикация на каждом сайте
                    bool success = PublishToSite(site, work);
                    if (!success)
                    {
                        MessageBox.Show($"Не удалось опубликовать {work.Title} на сайте {site}");
                    }
                }
            }

            MessageBox.Show("Работы опубликованы.");
        }

        private bool PublishToSite(string site, ArtWork work)
        {
            // Заглушка для публикации на сайт, замена на HTTP-запрос или API
            return true;
        }

        private List<string> SupportedSites()
        {
            // Поддерживаемые сайты
            return new List<string> { "Site1", "Site2", "Site3" };
        }

        private void btnGeneratePdf_Click(object sender, EventArgs e)
        {
            if (listBoxArtWorks.SelectedItem == null) return;

            var selectedWork = artWorks.Find(work => work.Title == listBoxArtWorks.SelectedItem.ToString());
            if (selectedWork != null)
            {
                GeneratePdf(selectedWork);
                MessageBox.Show("PDF создан.");
            }
        }

        private void GeneratePdf(ArtWork work)
        {
            // Формирование PDF с использованием iTextSharp
            using (FileStream stream = new FileStream($"{work.Title}.pdf", FileMode.Create))
            {
                Document pdfDoc = new Document(PageSize.A4);
                PdfWriter.GetInstance(pdfDoc, stream);
                pdfDoc.Open();
                pdfDoc.Add(new Paragraph("Название: " + work.Title));
                pdfDoc.Add(new Paragraph("Описание: " + work.Description));
                if (File.Exists(work.ImagePath))
                {
                    var img = iTextSharp.text.Image.GetInstance(work.ImagePath);
                    img.ScaleToFit(400f, 300f);
                    pdfDoc.Add(img);
                }
                pdfDoc.Close();
            }
        }

        private void btnCompressImage_Click(object sender, EventArgs e)
        {
            if (listBoxArtWorks.SelectedItem == null) return;

            var selectedWork = artWorks.Find(work => work.Title == listBoxArtWorks.SelectedItem.ToString());
            if (selectedWork != null && File.Exists(selectedWork.ImagePath))
            {
                CompressImage(selectedWork.ImagePath);
                MessageBox.Show("Изображение сжато.");
            }
        }

        private void CompressImage(string imagePath)
        {
            // Пример сжатия изображения
            using (var image = new Bitmap(imagePath))
            {
                var resizedImage = new Bitmap(image, new Size(800, 600)); // Сжатие до 800x600
                resizedImage.Save("Compressed_" + Path.GetFileName(imagePath), System.Drawing.Imaging.ImageFormat.Jpeg);
            }
        }
    }

    public class ArtWork
    {
        public string Title { get; set; }
        public string Description { get; set; }
        public string ImagePath { get; set; }
        public decimal Price { get; set; }
        public string Status { get; set; }
        // Дополнительные поля, такие как материал, техника и т.д.
    }

    public partial class ArtWorkForm : Form
    {
        private ArtWork artWork;
        public ArtWork GetArtWork()
        {
            // Форма для добавления информации о работе
            return artWork;
        }
    }
}
