        {
            InitializeComponent();
        }

        private void InitializeComponent()
        {
            // Настройка формы
            this.Text = "Art Uploader";
            this.Size = new Size(800, 600);

            // Панель инструментов
            toolBar = new ToolStrip();
            toolBar.Items.Add(new ToolStripButton("Добавить работу", null, btnAddWork_Click));
            toolBar.Items.Add(new ToolStripButton("Опубликовать", null, btnPublish_Click));
            toolBar.Items.Add(new ToolStripButton("Создать PDF", null, btnGeneratePdf_Click));
            toolBar.Items.Add(new ToolStripButton("Сжать изображение", null, btnCompressImage_Click));
            toolBar.Items.Add(new ToolStripButton("Настройки", null, btnSettings_Click));

            // Список работ (DataGridView)
            artWorksGrid = new DataGridView
            {
                Dock = DockStyle.Left,
                Width = 300,
                AutoGenerateColumns = false
            };
            artWorksGrid.Columns.Add("Title", "Название");
            artWorksGrid.Columns.Add("Material", "Материал");
            artWorksGrid.Columns.Add("Price", "Цена");
            artWorksGrid.SelectionChanged += ArtWorksGrid_SelectionChanged;

            // Панель для деталей выбранной работы
            detailsPanel = new Panel
            {
                Dock = DockStyle.Fill,
                Padding = new Padding(10)
            };

            artworkImage = new PictureBox
            {
                Size = new Size(200, 200),
                BorderStyle = BorderStyle.Fixed3D
            };

            txtTitle = new TextBox { ReadOnly = true };
            txtDescription = new TextBox { Multiline = true, ReadOnly = true, Height = 100 };
            txtPrice = new TextBox { ReadOnly = true };

            btnEdit = new Button { Text = "Редактировать" };
            btnDelete = new Button { Text = "Удалить" };

            // Добавление элементов на панель деталей
            detailsPanel.Controls.Add(new Label { Text = "Изображение:", Top = 10 });
            detailsPanel.Controls.Add(artworkImage);
            detailsPanel.Controls.Add(new Label { Text = "Название:", Top = 220 });
            detailsPanel.Controls.Add(txtTitle);
            detailsPanel.Controls.Add(new Label { Text = "Описание:", Top = 250 });
            detailsPanel.Controls.Add(txtDescription);
            detailsPanel.Controls.Add(new Label { Text = "Цена:", Top = 370 });
            detailsPanel.Controls.Add(txtPrice);
            detailsPanel.Controls.Add(btnEdit);
            detailsPanel.Controls.Add(btnDelete);

            // Добавление элементов на форму
            this.Controls.Add(toolBar);
            this.Controls.Add(artWorksGrid);
            this.Controls.Add(detailsPanel);
        }

        private void ArtWorksGrid_SelectionChanged(object sender, EventArgs e)
