        bool isActivated = LoadActivationState(); // Активированно (true or false)
        UpdateActivationStatus(isActivated);     // Обновление статуса
        FlowLayout();  // Обновляем галерею
    }

    public void FlowLayout()
    {
        // Очистим существующую панель, если нужно (например, при повторном вызове)
        flowLayoutPanel2.Controls.Clear();

        // Добавляем изображения в существующий FlowLayoutPanel (flowLayoutPanel2)
        for (int i = 0; i < 5; i++)
        {
