            picture.Click += Picture_Click;

            // Добавляем PictureBox в flowLayoutPanel2
            flowLayoutPanel2.Controls.Add(picture);
        }
    }

    // Обработчик события клика по изображению
    private void Picture_Click(object sender, EventArgs e)
    {
        // Если ранее было выбрано изображение, сбрасываем его выделение
        if (selectedPicture != null)
        {
            // Сброс стиля выбранного изображения
            selectedPicture.BorderStyle = BorderStyle.None;
        }

        // Устанавливаем новое выбранное изображение
        selectedPicture = (PictureBox)sender;

