function getHitPoint(clientX, clientY, objects, camera) {
    // Преобразование экранных координат в координаты устройства
    const mouse = new THREE.Vector2();
    mouse.x = (clientX / window.innerWidth) * 2 - 1;
    mouse.y = -(clientY / window.innerHeight) * 2 + 1;

    // Создание луча от камеры в направлении курсора мыши
    const raycaster = new THREE.Raycaster();
    raycaster.setFromCamera(mouse, camera);

    // Получение точки пересечения луча с объектами
    const intersects = raycaster.intersectObjects(objects);

    // Возвращение точки пересечения, если она есть
    if (intersects.length > 0) {
        return intersects[0].point;
    }

    return null;
}
