```javascript
// Функция для перемещения плоскости движения с помощью мыши
function moveMovementPlaneWithMouse(event, camera, movementPlane, axis) {
    // Получаем положение курсора мыши внутри элемента, на котором было событие
    const mousePosition = new THREE.Vector2();
    mousePosition.x = (event.clientX / window.innerWidth) * 2 - 1;
    mousePosition.y = - (event.clientY / window.innerHeight) * 2 + 1;

    // Создаем вектор для хранения позиции мыши в трехмерном пространстве
    const mouse3D = new THREE.Vector3(mousePosition.x, mousePosition.y, 0.5);
    mouse3D.unproject(camera);

    // Определяем направление перемещения в зависимости от выбранной оси
    let direction = new THREE.Vector3();
    if (axis === 'x') {
        direction.set(1, 0, 0); // По оси X
    } else if (axis === 'y') {
        direction.set(0, 1, 0); // По оси Y
    } else if (axis === 'z') {
        direction.set(0, 0, 1); // По оси Z
    }

    // Находим точку, в которую переместить плоскость движения
    const distance = -movementPlane.position.dot(direction) / mouse3D.dot(direction);
    const newPosition = mouse3D.clone().multiplyScalar(distance);

    // Перемещаем плоскость в новую позицию
    movementPlane.position.copy(newPosition);
}
```

