```javascript
// This function moves the virtual movement plane for the mouseJoint to move in
function moveMovementPlane(point, camera) {
    // Center at mouse position
    movementPlane.position.copy(point);

    // Make it face toward the camera
    movementPlane.quaternion.copy(camera.quaternion);

    // Update cube's vertices positions
    const vertices = cube.geometry.vertices;
    for (let i = 0; i < vertices.length; i++) {
        // Get the world position of each vertex
        const vertexWorldPosition = vertices[i].clone().applyMatrix4(cube.matrixWorld);

        // Calculate the vector from the current vertex position to the movement plane position
        const vectorToPlane = movementPlane.position.clone().sub(vertexWorldPosition);

        // Update the position of the vertex by adding the vector to the movement plane position
        vertices[i].add(vectorToPlane);
    }

    // Notify Three.js that the geometry vertices have been updated
    cube.geometry.verticesNeedUpdate = true;

    // Update the physics body of the cube with the new vertices positions
    updateCubeBody();
}

// Function to update the physics body of the cube with the new vertices positions
function updateCubeBody() {
    // Assuming cubeBody is the Cannon.js body of the cube
    const vertices = cube.geometry.vertices;
    const positions = [];
    for (let i = 0; i < vertices.length; i++) {
        // Convert the local vertex position to world coordinates
        const vertexWorldPosition = vertices[i].clone().applyMatrix4(cube.matrixWorld);
        positions.push(new CANNON.Vec3(vertexWorldPosition.x, vertexWorldPosition.y, vertexWorldPosition.z));
    }

    // Update the body's shape with the new vertices positions
    cubeBody.shapes[0] = new CANNON.ConvexPolyhedron(positions, cube.geometry.faces.map(face => face.normal.clone()));

    // Update the body's bounding radius
    cubeBody.updateBoundingRadius();

    // Update the body in the physics world
    world.updateBody(cubeBody);
}
```

