// массива в выражении [array[i], array[j]] = [array[j], array[i]] и поменять местами элементы "i" и "j" в массиве
// в результате каждой иттерации цикла элементы массива будут перемешаны случайным образом
// После выполнения функции, исходный массив будет изменен и будет содержать те-же элементы но в случайном порядке
function shuffleQuestions(array) {
  for (let i = array.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [array[i], array[j]] = [array[j], array[i]];
  }
}

